    "storyCause": "受害人林建宏為承攬北市多項科技標案的專案採購經理，平日作風霸道且習慣惡意拖延下游外包工程款，導致多家小包商面臨資金斷裂破產。案發當天下午兩點，林建宏約了被欠款的外包工程師張世傑與同組競爭升遷的資深業務許雅筑，在西門町成都路連鎖咖啡店二樓靠窗桌洽談和解與分潤。各方心懷鬼胎，桌底下早已暗流洶湧。",
    "storyProcess": "林建宏點了招牌熱焦糖瑪奇朵（Hot Caramel Macchiato）。吧檯調配員吳冠宇將咖啡端上桌後，林建宏一邊高聲接聽商業電話、一邊索取方糖。外包商張世傑順手替他撕開方糖包倒入杯中攪拌。林建宏習慣邊講電話邊喝熱飲且絕不拆杯蓋，直接對準杯蓋飲用孔仰頭吸吮熱飲。不料剛吸入第一口，隨即臉色發青、雙手掐頸劇烈抽搐，翻倒咖啡杯倒地昏迷！店家立刻按下警報器拉下二樓門禁防護並撥打 119 與 110。都會調查員接獲通報迅速步行趕赴現場。現場封鎖後，員警陳隊長初步調查發現：張世傑曾公開揚言要林建宏付出代價；許雅筑第一時間竟伸手搶奪林建宏的手機企圖塞入皮包；而吧檯調配員吳冠宇則堅稱自己全程配戴食品手套、從密封消毒盒拿取杯蓋，絕無接觸毒物。",
    "storyClimax": "都會調查員採集打翻的咖啡殘液與杯蓋進行採樣，確認致病因子為苦杏仁提取物水解之劇毒氰化氫（HCN 氣體）與未完全水解之苦杏仁苷雙糖氰苷母體。經鑑識排查：張世傑包包內的備用方糖包純為食用蔗糖，手指無任何毒物殘留；許雅筑搶手機是為刪除私人曖昧對話。調查員仔細檢視 4 號桌杯蓋，在 365nm 紫外線鑑識燈下赫然發現：塑膠杯蓋內緣飲用孔處有一層微薄凡士林脂質疏水膜，且卡榫處留有滲透手套微孔的右手食指汗液指紋痕跡，比對正是吧檯調配員吳冠宇！原來招牌熱焦糖瑪奇朵表面覆有綿密厚奶泡與焦糖醬網格，濃郁焦甜香恰好在出餐時掩蓋了水解初期微弱的苦杏仁氣味；吳冠宇身為吧檯調配員，正是藉著在吧檯淋擠焦糖醬網格為掩護，暗中將混有苦杏仁苷與伴生苦杏仁酵素（Emulsin）粉末的疏水凡士林塗抹於杯蓋飲用孔內緣。當杯蓋扣在 65°C 的熱焦糖瑪奇朵上，溫熱蒸氣活化酵素迅速水解釋出 HCN 氣體與苯甲醛；受害人林建宏對準飲用孔吸吮時，第一口先經呼吸道吸入揮發性 HCN 氣體，隨後熱奶泡沖刷經口腔黏膜吞入未完全水解之苦杏仁苷母體，造成雙重致毒抽搐昏迷！而在杯蓋凡士林未水解殘渣中，TLC 矽膠薄層層析板展開帶顯示苦杏仁苷特異斑點（Rf = 0.42），氣體揮發與塗抹殘渣完美自洽，指紋鐵證如山，吳冠宇無法抵賴，低頭認罪伏法。",
