    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：可彎曲透明吸管 1 支、免洗紙杯 1 個、剪刀、水。原理：",
    "brief": "高鐵外包清潔承攬公司組長彭耀華，平日苛扣派遣工工時與全勤獎金，甚至將昂貴的工業級超音波地板打蠟機報廢零件私吞轉賣。案發當晚八點四十五分，長廊轉角清潔機房突發一聲震耳欲聾的金屬砸地巨響，引發過往通勤族恐慌圍觀。警衛趕到時，價值三十萬元的精密檢測儀已被砸成廢鐵，機房門口遺留一灘清水。",
    "storyCause": "高鐵外包清潔承攬公司組長彭耀華，平日苛扣派遣工工時與全勤獎金，甚至將昂貴的工業級超音波地板打蠟機報廢零件私吞轉賣。案發當晚八點四十五分，長廊轉角清潔機房突發一聲震耳欲聾的金屬砸地巨響，引發過往通勤族恐慌圍觀。警衛趕到時，價值三十萬元的精密檢測儀已被砸成廢鐵，機房門口遺留一灘清水。",
    "storyProcess": "值班保全通報都會調查員到場協助。調閱監視器畫面，事發時間為 20:45:10，然而涉有重嫌的三名清潔員與一名維修工程師皆提出完美不在場證明：工程師在 300 公尺外的高鐵剪票口刷卡進站；清潔員趙大嬸正在 B1 台鐵服務台簽到；而最被懷疑被扣薪的年輕清潔員郭子豪，在事發前十分鐘（20:35）就已被站務員目擊在地面大廳吃便當。機房內部沒有任何人員藏匿，天花板僅有一條冷氣冷凝水排水塑膠軟管。都會調查員實地步行勘查，發現機房高處置物架上有一個倒扣的大型 5 公升清潔劑空桶，桶底有鑽孔痕跡，且桶內殘留一根折彎的透明塑膠吸管。",
    "storyClimax": "都會調查員立即運用物理流體力學進行推導：這是一個利用冷氣排水滴漏的「虹吸管定時洩水機關」！兇手預先將沉重的鐵質扳手用粗棉繩綁住置物架邊緣，棉繩另一端懸掛盛水桶。冷氣冷凝水以每分鐘約 150 毫升速度滴入桶中，當水位上升超過虹吸管最高點（彎折處約 20 公分高），大氣壓與液壓差瞬間啟動全速排水，失衡的重力使槓桿滑動，將高處置物架上的廢棄鋼梁砸下擊毀儀器。經注水實測，蓄水達虹吸峰值恰好需 35 分鐘！這意味著機關布設時間為 20:10 左右。都會調查員調取各出入口悠遊卡與打卡紀錄，20:10 唯一單獨進入該機房取推車的，正是清潔組長彭耀華自己！原來彭耀華私下盜賣儀器內部昂貴白金感測晶片，為了掩蓋侵占事實，自導自演製造外力砸毀意外企圖詐領保險金並嫁禍下屬。面對虹吸管還原實驗與晶片藏匿點起獲，彭耀華百口莫辯。",
