    "scienceConcept": "露點凝結光學折射（Dew Point Condensation）、皮脂疏水性（Sebum Hydrophobicity）與脂溶性微膠囊隱形防偽螢光油墨鑑識。超商立式冷藏展示櫃（Reach-in Cooler）常於正面拉門外緣加裝專用透明壓克力展示側檔板，表面溫度維持在約 4℃~6℃，遠低於台北夏季室內露點（約 21℃）。當拉開拉門數秒引導室內溫濕空氣對流時，水氣迅速在冰冷壓克力檔板上凝結成均勻漫反射微細水霧；而人體手指沾附之皮脂因疏水性阻隔水膜成核，在 45 度斜射掠射側光下形成反差比大於 85% 之極清晰指紋。此外，店方在展示盒金屬扣環預塗之隱形防偽油墨採用脂溶性微膠囊基質，能極速滲入指紋脊紋隙縫凹槽深處；即便嫌犯作案後特意用面紙擦拭壓克力盒表面，指腹凹槽內仍牢固嵌留無法抹去之高濃度螢光印記，在 365nm 紫外線激發下激發刺眼黃綠色螢光。",
