    "brief": "漢中街超商當日清晨上架全台限量二十套的動漫限定「幻影雷射金屬卡」，一套市價高達上萬元。超商配合夏日冰飲促銷，將加價購展示盒磁吸固定於低溫飲料冷藏展示櫃正面拉門外緣與專用透明壓克力展示側檔板上。為防止偷竊，店長特意在展示盒精鋼扣環上預先塗抹了微量脂溶性微膠囊隱形防偽螢光油墨。午後兩點，店員赫然發現展示盒的機械壓扣鎖遭撬開，盒內編號 001 的首發金屬卡不翼而飛！",
    "storyCause": "漢中街超商當日清晨上架全台限量二十套的動漫限定「幻影雷射金屬卡」，一套市價高達上萬元。超商配合夏日冰飲促銷，將加價購展示盒磁吸固定於低溫飲料冷藏展示櫃正面拉門外緣與專用透明壓克力展示側檔板上。為防止偷竊，店長特意在展示盒精鋼扣環上預先塗抹了微量脂溶性微膠囊隱形防偽螢光油墨。午後兩點，店員赫然發現展示盒的機械壓扣鎖遭撬開，盒內編號 001 的首發金屬卡不翼而飛！",
