    "storyClimax": "都會調查員敏銳觀察到展示盒原先磁吸緊貼在低溫冷藏展示櫃正面拉門外緣的透明展示側檔板上。調查員請店員將冷藏拉門微開數秒，引導室內溫暖潮濕空氣湧向側檔板，冰冷的透明壓克力板表面瞬間凝結出大片白茫茫的均勻細微水霧！在便攜式強光手電筒的 45 度斜射掠射光照射下，一組極為清晰完整的右手掌紋與食指指紋在水霧背景中赫然浮現！指紋受力向量明顯向下，證實有人曾以右手用力反撐住低溫展示檔板以支撐身體重量、伸出左手撬開扣環；該枚掌紋與王志遠完全吻合。更致命的是，調查員取出 365nm 紫外線鑑識手電筒照射王志遠雙手：因防偽油墨採用脂溶性微膠囊基質，極易滲入指紋脊紋隙縫，即使他事後用面紙擦拭壓克力表面，其右手指腹凹槽內仍殘留無法抹去的高濃度螢光印記，在紫光下發出刺眼綠光！隨後在王志遠左腳球鞋鞋墊夾層中搜出編號 001 的限量金屬卡原件。在物理水霧指紋與脂溶性螢光油墨雙重鐵證下，王志遠低頭認罪伏法。",
