    "difficulty": "★★★☆☆",
    "spookiness": "👻☆☆☆☆ (溫和日常)",
    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "牛頓第一運動定律（慣性定律）與達朗貝爾慣性力（Inertial Force Fin = -m·a）向量力學，搭配捷運列車自動防護系統（ATP）保護迴路與車載廣角監控視角死角鑑識。捷運重軌列車（如 C321/C341 車型）全斷面車廂通道為密封防護風擋，乘客無法向外拋擲雜物；然而門側緊急手動排氣閥（Emergency Evacuation Door, EED）檢修隙縫若遭導電金屬片插入短路，將觸發安全迴路連鎖開路，迫使 ATP 實施負加速度高達 -1.3 m/s² 的保護性急煞。在車廂急煞瞬間，乘客相對車廂受到強大向前的慣性假想力；若無外力支撐人體必向前撲倒，絕無可能向後滑行。嫌犯預先雙手反扣固定立柱鋼管作為剛性反作用力支點，藉由手臂拉力與立柱槓桿力矩克服慣性衝擊，順應急煞前衝力低重心翻滾精準勾出座椅下方背包；並以長版風衣與懸掛立柱上方之長傘製造長達 3 秒之車載監視器下盤死角。",
