    "brief": "深夜 00:25，台北捷運板南線開往南港展覽館的末班車，在剛駛離台北車站進入善導寺站區間的地底深層隧道時，車載號誌系統突傳異狀，觸發自動列車防護系統（ATP）連鎖保護，列車以 -1.3 m/s² 實施緊急煞車！全車猛烈震盪。坐在第三車廂博愛座旁的科技公司財務長何銘輝，其放置於座位下方、內裝兩百萬元不記名商業本票與加密隨身碟的黑色公事包，竟在急煞一片混亂中離奇消失，只留下一只外觀完全相同的空包！",
    "storyCause": "深夜 00:25，台北捷運板南線開往南港展覽館的末班車，在剛駛離台北車站進入善導寺站區間的地底深層隧道時，車載號誌系統突傳異狀，觸發自動列車防護系統（ATP）連鎖保護，列車以 -1.3 m/s² 實施緊急煞車！全車猛烈震盪。坐在第三車廂博愛座旁的科技公司財務長何銘輝，其放置於座位下方、內裝兩百萬元不記名商業本票與加密隨身碟的黑色公事包，竟在急煞一片混亂中離奇消失，只留下一只外觀完全相同的空包！",
    "storyProcess": "何銘輝大驚失色，立刻按下車門旁緊急通話鈕向司機員求救。列車於善導寺站 2 號月台緊急停靠後，站長與在站體巡檢的都會調查員迅速封鎖該節車廂。深夜末班車該車廂內乘客極其稀少，除何銘輝外僅有三人：身穿黑色長版風衣的系統工程師周啟凡、手提工具包的快遞員葉書宏、以及剛下小夜班的護理師陳雅婷。周啟凡聲稱自己手拉立柱站立，急煞時差點跌倒，對公事包毫不知情。調查員調閱車廂頂部廣角行車 CCTV 監視錄影，發現周啟凡在列車急煞前三十秒，刻意將隨身攜帶的一柄黑色折疊長傘懸掛於立柱扶手上方特定角度，其長版風衣下擺與長傘傘面在俯瞰鏡頭前巧妙重疊，恰好形成了針對其腳步與座位下盤長達 3 秒鐘的視覺死角！",
    "storyClimax": "都會調查員會同捷運工務段技術人員實施車體詳細鑑識，在第三車廂門側「緊急手動排氣閥（EED）」檢修外蓋隙縫中，起獲了一片帶有絕緣手柄的特製磷銅導電短路片！正是這枚短路片瞬間短接了門控端子，人為誘發了 ATP 系統的 -1.3 m/s² 急煞保護。更具決定性的是物理力學分析：在 -1.3 m/s² 猛烈急煞下，所有乘客受慣性假想力驅使均身不由己向前衝撲；但行車監視器以高格率慢速重放時，捕捉到周啟凡在急煞瞬間，雙手肌肉爆發出反向拉力死死抓扣固定鋼柱，以鋼柱為剛性支點對抗向前的假想力，藉手臂拉力與立柱槓桿迅速完成重心低位旋轉，順勢將右腳滑入何銘輝座椅下方的空隙精準勾出公事包並推入預先放置的空包調包！調查員隨即搜查周啟凡的長版風衣內側特製深暗袋，當場搜出何銘輝失竊的兩百萬元商業本票與加密隨身碟，短路金屬片上更驗出周啟凡的皮膚碎屑。周啟凡無言以對，伏法認罪。",
