    "storyCause": "淡水古蹟博物館在整修淡水海關碼頭 C 棟紅磚倉庫時，在老庫房深處發掘出一只 1860 年代清末英國「寶順洋行」純銅航海保險箱。箱體正面鑲嵌著 26 塊刻有 1860 年代英國皇家海軍海事旗語代碼的活動滑塊，並刻有一篇包含 128 個持旗符號的長篇航海日誌草稿，疑似記載著百年前滬尾稅關的黃金密件！昨夜，巡邏警衛赫然發現倉庫邊門門鎖受損，保險箱右下角被砂輪機切開一道深痕，內部雙動簧片死鎖阻鐵被觸發卡死保險栓！若未在今晨以前解碼並推入正確滑塊齒輪釋放阻鐵，保險栓將永久咬死。",
    "storyProcess": "展館立即通報都會調查員到場。涉案關係人包括：古董修復師何啟文、文史研究生周漢廷、以及碼頭維護技工沈正德。沈正德堅稱自己整晚只在乾淨的老街石板步道散步，絕未踏入泥地或碰過保險箱；周漢廷則辯稱自己在研究室研讀文獻，對保險箱受損毫不知情。調查員勘查現場：海關碼頭外緣為數公尺高的垂直重力式砌石碼頭，深水供大船停泊，正下方並無泥灘紅樹林；然而沈正德所穿的專業防滑涉水鞋底深溝中，卻緊緊嵌塞著大量濕潤的微鹹黑泥，以及水筆仔胚軸的特異植物纖維！淡水河口真正的水筆仔原生紅樹林保護區位於捷運竹圍至紅樹林站一帶，調查員推斷其必是自竹圍潮間帶取藏匿之重型砂輪切割機後潛行至現場。",
    "storyClimax": "都會調查員將目光移回保險箱的旗語密文：草稿全篇共有 128 個皇家海軍海事旗語符號。調查員展開英文字母頻率分析：在 128 個符號中，雙手斜下 45 度持旗的符號累計出現了整整 16 次，佔比 12.5%，在大數統計法則下精準對應英文最高頻字母「E」；隨後次高頻符號對應「T」與「A」。調查員迅速解碼出整篇航海日誌草稿，並破譯出解除防鋸阻鐵的核心密碼單字——「ANCHOR（鐵錨）」！調查員依序滑動正面滑塊拼出「A-N-C-H-O-R」，按壓錨型青銅按鈕，內部機械雙動簧片阻鐵清脆彈開，保險箱門應聲開啟，起獲 1860 年代寶順洋行地契存根！警方隨後在竹圍紅樹林退潮泥灘沈正德藏匿處搜出沾滿水筆仔胚軸碎屑的手持充電式砂輪機，砂輪片上殘留寶順洋行特種古青銅金屬碎屑。沈正德無從抵賴，俯首認罪。",
