    "scienceConcept": "弱有機酸高熱乾脫水炭化反應（Dehydration of Cellulose）、365nm 長波紫外線黃酮類無損初檢、以及民法自書遺囑要件全程鑑識。檸檬汁富含檸檬酸（Citric Acid）與天然柑橘類黃酮。高濕度之溫泉水蒸氣（約 75℃）富含水分，會阻礙酸脫水反應且使和紙吸水軟爛、字跡暈開；真正之顯影原理為：先以 365nm 紫外線鑑識燈對空白宣紙進行無損初檢，激發檸檬汁中柑橘類黃酮發出微弱淡黃綠色自體螢光，鎖定隱蔽筆劃字跡；隨後使用 140℃ 乾熱熨斗隔吸墨紙低溫乾熨 30 秒，檸檬酸在乾燥高熱下奪走纖維素分子中之水分子，催化紙張纖維低溫脫水轉變為深褐色炭化物，使毛筆楷書字跡清晰顯現。見證律師全程錄影見證顯影過程，證實簽名與筆跡無誤，符合自書遺囑法定要件。",
