    "storyCause": "北投幽雅路擁有百年歷史的日式檜木溫泉旅館「松濤閣」，高齡老業主林松濤病逝，家族與見證律師黃國彰齊聚書房宣讀遺囑。律師從書桌保險櫃取出老先生親自以火漆私章密封之厚信封，在眾人面前剪開封籤，抽出的上等和宣紙信紙上竟一片空白、空無一字！長子林慶宗當場冷笑斥責此為無效廢紙，主張按法定應繼分繼承全數土地以進行高額都更開發；而侍奉老先生整整五十年的老總管陳阿財則熱淚盈眶，堅稱老創辦人昨夜臨終前曾耳提面命：「真遺願藏在乾熱的火光裡，不可見水！」",
