    "storyClimax": "都會調查員關閉書房燈光，開啟 365nm 紫外線鑑識手電筒進行無損光學初檢：在深暗背景下，宣紙上微弱的柑橘類黃酮受激發發出淡黃綠色的微弱自體螢光，清楚呈現出一排排蒼勁的毛筆隱形字痕！確認字跡位置後，調查員鋪上專用吸墨紙，使用溫控乾熨斗調至 140℃，對宣紙進行均勻乾熱熨燙 30 秒；在乾燥高熱催化下，檸檬酸瞬間使紙張局部植物纖維脫水炭化，短短半分鐘內，深褐色的毛筆楷書字跡赫然深刻顯影！見證律師黃國彰全程錄影見證。遺囑首行寫明：「吾以客房新鮮檸檬汁蘸筆立此暗墨，防逆子盜改⋯⋯老旅店由終生守護溫泉老灶、無怨無悔服務五十年的總管陳阿財與次女林雅慧共同繼承，永不拆除都更！」簽名、印章與年月日清晰完備，經律師錄影見證確認具備完整自書遺囑法律效力。長子林慶宗奪產企圖落空，頹然癱坐在地。",
