    "storyCause": "科教館閉館前夕，五樓光學常設展區最昂貴的展示器材——一套由德國進口、價值五十萬元的特種「532nm 半導體泵浦固態綠光雷射精密準直儀（DPSS 雷射儀）」，在展演結束後驚傳失竊！奇怪的是，四周的紅外線防盜光網居然全程未曾觸發斷訊警報，唯有下午三點整，展台防盜主機曾短暫記錄下一筆來自展台基座高靈敏度壓電微震感應器（Piezoelectric Sensor）的 0.2G 異常微震動警訊！",
    "storyProcess": "展館緊急封館並通報都會調查員。涉案關係人共有三人：光學儀器工程師柯大為、展區器材維護員李冠廷、以及兼職導覽大學生吳佩珊。柯大為辯解：『我只是受邀來檢驗鏡面迷宮的校準度，我隨身帶的都是普通筆電和測量尺，展台四周的紅外線光幕根本沒響過警報，你們不能無端搜查我的工程包！』調查員勘查展台：天花板四道垂直向下的不可見紅外線防盜光束依然精準照射在地面接收端子孔內。如果僅用兩面平面鏡，光線只會平行偏折到旁邊地板，絕不可能繞過展台又垂直打回原地底感應器；調查員仔細檢視展區迷宮的大型活動平面鏡，赫然發現其中四面鏡子被巧妙組合成了一組四面立體直角潛望幾何反射鏡組！",
    "storyClimax": "都會調查員當場指出柯大為的手法：柯大為利用自備的高速光學切換擋板（遮光延遲小於 0.03 秒），在低於系統 0.05 秒斷訊閾值內，將垂直光束藉由上方兩面 45 度鏡折為水平繞過展台，再經由下方兩面鏡折回垂直射入原地面接收器！然而他千算萬算，忽略了展台基座安裝的壓電微震感應器，在下午三點他以工業級微型真空吸盤提起展示玻璃罩時，產生了 0.2G 瞬間微震日誌！調查員使用鑑識光源照射鏡組微調旋鈕，採集到特異的紅外線感光顯影卡微粒粉末；隨後在柯大為工程筆電包側袋中，搜出同批號未乾的紅外顯影卡、專用六角光學微調扳手、以及用防震泡棉包裹的 532nm 固態綠光準直儀！面對精密微震日誌、幾何潛望鏡組與人贓俱獲，柯大為面如死灰，只得俯首認罪。",
