    "difficulty": "★★☆☆☆",
    "spookiness": "👻👻👻☆☆ (暗夜懸疑)",
    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "固體壓強物理定律（P = F / A）、疏水特氟龍排泥板鞋壓強分攤機制、植物禾本科草葉角質層光學漫反射折射差鑑識、以及現代數位全片幅 RAW 檔 CFexpress 記憶卡鑑識。暴雨沖刷後之鬆軟黑土草坪極限剪切壓強約為 3.5 kPa 至 4.0 kPa，成年人體重（約 70kg）穿一般球鞋接觸面積約 250 cm²，壓強高達約 28 kPa，踩入泥濘必深陷 3 至 5 公分。嫌犯使用特製長 65cm、寬 35cm、底部具備疏水特氟龍塗層之碳纖維滑行大排泥板鞋，使接觸總面積大幅擴大至 4550 cm²，將總壓強大幅降至 3.2 kPa 以下，小於草皮破裂臨界值，故未深陷黑泥；然而特氟龍板邊緣滑行時仍壓折了禾本科草葉表層蠟質角質層，在 365nm 紫光鑑識燈斜射下呈現連續特異的光學漫反射折射差痕跡。此外，現代旗艦攝影器材使用 CFexpress 記憶卡儲存未備份 8K RAW 原始檔，徹底排除傳統底片穿幫。",
    "curriculumMapping": "固體壓強物理定律（P = F / A）、疏水特氟龍排泥板鞋壓強分攤機制、植物禾本科草葉角質層光學漫反射折射差鑑識、以及現代數位全片幅 RAW 檔 CFexpre...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：裝滿濕軟泥土（或麵粉）的淺盤、重物（如鉛筆盒或水瓶）、大塊硬紙板。原理：",
    "brief": "雷雨交加的週五深夜，大安森林公園生態水池中央的孤島濕地復育觀測木台上，野鳥生態攝影名家趙宏博，正架設著市價逾四十萬元的 600mm F4 頂級定焦巨砲鏡頭與旗艦相機機身，通宵守候罕見的五色鳥與夜鷺育雛畫面。因暴雨增強，趙宏博轉身穿過涉水跳石回到公廁後方器材棚拿取防水防雨套，來回約耗時 6 至 8 分鐘。當他返回木台時，赫然發現腳架上的 600mm 巨砲鏡頭、旗艦機身及裝有即將參賽獲獎 8K RAW 檔的 CFexpress 記憶卡整組遭人旋下盜走！",
    "storyCause": "雷雨交加的週五深夜，大安森林公園生態水池中央的孤島濕地復育觀測木台上，野鳥生態攝影名家趙宏博，正架設著市價逾四十萬元的 600mm F4 頂級定焦巨砲鏡頭與旗艦相機機身，通宵守候罕見的五色鳥與夜鷺育雛畫面。因暴雨增強，趙宏博轉身穿過涉水跳石回到公廁後方器材棚拿取防水防雨套，來回約耗時 6 至 8 分鐘。當他返回木台時，赫然發現腳架上的 600mm 巨砲鏡頭、旗艦機身及裝有即將參賽獲獎 8K RAW 檔的 CFexpress 記憶卡整組遭人旋下盜走！",
    "storyProcess": "趙宏博心急如焚通報都會調查員趕抵現場。該孤島觀測木台因步道翻修暫時拆除木棧道，周遭環繞著寬達 15 公尺、因大雨沖刷而極度泥濘鬆軟的黑土草坪。任何成年人若徒步走過，必定會在爛泥中留下深達三至五公分的深陷腳印；然而在手電筒照射下，四周泥濘草坪上居然「空無一印」！案發時間在公廁涼亭避雨的有三人：同為生態攝影師的競爭對手吳德貴、夜跑躲雨的上班族高偉翔、以及公園園藝外包工陳阿發。三人鞋底均乾淨無厚重爛泥。吳德貴冷笑：『那片爛泥踩進去鞋子拔都拔不出來，現場連個腳印都沒有，難道小偷會輕功水上漂？趙宏博自己沒看好器材別賴在別人頭上！』",
    "storyClimax": "都會調查員蹲在草坪邊緣仔細觀察，開啟 365nm 紫外線鑑識手電筒配合強光側射：在泥草交界處，赫然發現草坪表層並非毫無痕跡——有一串寬達 35 公分的規則扁平草葉微弱壓痕！調查員指出：依據固體壓強公式 P = F / A，人體重量若平均分攤在超大受力面積上，壓強可降至土壤剪切極限 3.5 kPa 以下！調查員循著草葉角質層折射差痕跡一路追蹤至公廁後方大型堆肥桶，在桶底暗格起獲了一雙長 65cm、寬 35cm、底層包覆疏水特氟龍塗層的特製碳纖維滑行排泥板鞋！緊接著，在隔壁枯葉推肥桶夾層內，搜出了用黑色防水布緊密包裹的四十萬元 600mm F4 巨砲鏡頭、旗艦相機機身，以及插在卡槽內、存有珍貴獲獎候選夜鷺育雛 8K RAW 檔的 CFexpress Type B 高速記憶卡！排泥板鞋綁帶上驗出吳德貴的汗液 DNA，板底特氟龍縫隙更檢出與趙宏博腳架快拆板完全吻合的防滑墊橡膠微粒。吳德貴在科學鐵證下頹然低頭認罪。",
