    "scienceConcept": "國際海事雙旗信號旗語（International Maritime Semaphore Flags）標準手勢幾何角度編碼、微距鏡頭金屬接環外壁達瑪上光樹脂（Dammar Varnish）微物鑑識、以及清末領事官邸實木畫框三稜暗格鑰匙與壁爐渡鴉機關因果鎖定。標準國際海事旗語角度定義：C 為右手斜上 45 度（1點半方向）、左手垂直向下（6點鐘方向）；R 為雙手水平伸展呈 180 度（右手3點鐘、左手9點鐘）；O 為右手水平指向右側（3點鐘）、左手斜上右側交叉（1點半方向）；W 為左手水平指向左側（9點鐘）、右手斜上左側交叉（10點半方向）；P 為左手水平指向左側（9點鐘）、右手垂直指天（12點鐘方向）。嫌犯割開借展油畫背板夾層，旨在盜取老領事封存於畫框實木背板內之 1870 年代純銅特製三稜鑰匙；取得鑰匙後，再根據畫作旗語破譯出的密碼手勢（C-R-O-W，渡鴉）以鑰匙開啟官邸壁爐頂端之玄武岩渡鴉暗格取出淡水開港稅關印章拓本。",
