    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：紅黃雙色色紙 2 張（或免洗竹筷綁紅黃方巾 2 面）。原理：",
    "brief": "淡水紅毛城籌辦英國領事館修復特展前夕，英國文史信託基金會送交一幅 1875 年清末英國領事館水手手繪油畫《夕照滬尾港》。畫中水兵手持雙旗擺出特異信號姿勢。展出前夕清晨，保全驚覺懸掛油畫的實木畫框背板遭利刃割開一道整齊切口！館方大驚失色，深恐展品受損，緊急通報封館排查。",
    "storyCause": "淡水紅毛城籌辦英國領事館修復特展前夕，英國文史信託基金會送交一幅 1875 年清末英國領事館水手手繪油畫《夕照滬尾港》。畫中水兵手持雙旗擺出特異信號姿勢。展出前夕清晨，保全驚覺懸掛油畫的實木畫框背板遭利刃割開一道整齊切口！館方大驚失色，深恐展品受損，緊急通報封館排查。",
    "storyProcess": "都會調查員受託趕抵二樓領事官邸客廳。現場涉案關係人包括：負責油畫表面防護上光油的助理修復師周漢廷、淡水在地文史收藏家何啟文、以及巡館警衛趙大勇。何啟文聲稱自己只是站在走廊拿相機拍攝官邸窗櫺，絕未碰觸油畫或走近壁爐；周漢廷則辯稱自己整夜在修復室調配光油。調查員勘查油畫：割開畫布背板並非為了在畫框內找寶物，而是實木背板夾層內原藏有一把 1870 年代純銅特製三稜鑰匙已遭盜走！而官邸壁爐頂端的玄武岩渡鴉雕刻卡榫處，留有新鮮的金屬劃痕。調查員檢驗何啟文隨身攜帶的高階單眼相機：何啟文胸前懸掛的微距鏡頭金屬卡口接環外壁與鏡身對焦環滾花隙縫中，赫然沾染了微量尚未完全固化的達瑪天然光油（Dammar Varnish）與熟核桃油殘膠，與畫框背板封邊光油成份完全一致！",
    "storyClimax": "都會調查員當場以國際海事旗語標準角度破譯《夕照滬尾港》畫中水兵的旗語姿態：第一姿態（右手斜上 45 度、左手垂直向下）精確對應字母「C」；第二姿態（雙手水平伸展呈 180 度）對應字母「R」；第三姿態（右手水平右側、左手斜上右側交叉）對應字母「O」；第四姿態（左手水平左側、右手斜上左側交叉）對應字母「W」！四個字母組合為關鍵字「CROW（渡鴉）」！調查員隨即搜查何啟文的攝影包夾層，當場起獲了自畫框背板割取出的純銅三稜鑰匙！調查員將鑰匙插入壁爐頂端玄武岩渡鴉雕刻之眼部暗孔，順時針旋轉三圈，壁爐側壁暗格應聲彈開，珍藏百年的 1870 年代淡水開港稅關印章拓本完好起獲！在旗語密碼解析、接環光油殘膠與起獲三稜鑰匙鐵證下，何啟文無法辯解，認罪伏法。",
