    "scienceConcept": "阿基米德浮力定律（F浮 = ρ液 × V排 × g）、耐高壓金屬球型浮標抗黏滯密碼槽設計、實驗室金屬定量比重瓶（Pycnometer）恆溫秤重法、以及高黏稠非牛頓流體與焦糖色素稀釋液密度鑑識。正宗特調阿給紅糟甜辣醬富含味噌、紅糟與澱粉勾芡，黏度高且密度高達 1.25 g/cm³；傳統玻璃浮秤直接插入糊醬會因黏滯阻力卡死，老店浮力密碼箱特採耐高壓金屬球型浮標與低摩擦特氟龍導軌；都會調查員使用定量鑑識比重瓶恆溫稱重法精確測量，真原汁密度達 1.25 g/cm³，而嫌犯盜走 20 公升原汁後企圖拖延時間所調配之自來水焦糖色素水密度僅有 1.04 g/cm³。",
