    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：透明水杯 4 個、食用色素（紅、黃、藍、綠）、砂糖、熱水、細滴管。原理：",
    "brief": "淡水渡船頭傳承三代、每日排隊上百公尺的「金牌阿給」老店，創始老掌櫃病重休養前，將多家餐飲集團開價千萬的「祖傳秘製紅糟甜辣醬配方手冊」鎖在後廚水槽旁的特製浮力機關保險箱內。清晨備料時，二代店主發現廚房中央儲醬大不銹鋼桶被動過手腳，且浮力密碼箱的進料槽被不明殘渣卡死，配方手冊險遭破壞！",
    "storyCause": "淡水渡船頭傳承三代、每日排隊上百公尺的「金牌阿給」老店，創始老掌櫃病重休養前，將多家餐飲集團開價千萬的「祖傳秘製紅糟甜辣醬配方手冊」鎖在後廚水槽旁的特製浮力機關保險箱內。清晨備料時，二代店主發現廚房中央儲醬大不銹鋼桶被動過手腳，且浮力密碼箱的進料槽被不明殘渣卡死，配方手冊險遭破壞！",
    "storyProcess": "二代店主心急如焚通報都會調查員到場協助。浮力保險箱構造極其考究：中央設有一具耐高壓金屬球型浮標，浮標頂部嵌有磁簧開關鑰匙。依據老掌櫃設計，槽壁附有特氟龍抗黏導軌，唯有將真正煮得恰到好處、密度達 1.25 g/cm³ 的特製紅糟濃縮原汁注入外槽，球型浮標所受浮力方能克服重力與微弱黏滯阻力浮起解鎖；若密度不足則卡死。涉案關係人包括：廚藝精湛但欠下巨債的資深主廚高震東、外場資深領班鄭淑美、以及負責進貨洗碗的學徒許家豪。高震東堅稱大桶裡的醬汁全是他昨晚依古法現熬的真原汁，自己絕無偷換。",
    "storyClimax": "都會調查員取出鑑識專用金屬定量比重瓶（Pycnometer）與電子天平，對後廚儲醬大桶進行恆溫精確測量：測得大桶內液體密度竟然驟降至僅有 1.04 g/cm³，與真原汁的 1.25 g/cm³ 相去甚遠！調查員指出：高震東在昨夜利用手動抽油泵將 20 公升真正的高比重濃縮原汁全數抽走，藏匿於後港舢舨的柴油桶夾層中；為了掩蓋大桶醬汁失竊並拖延店方察覺時間，他在大桶內灌入大量稀釋自來水與工業焦糖色素偽裝體積；而在偷竊前，他曾企圖將未完全過濾之濃稠殘渣猛烈灌入密碼槽企圖強行開啟，導致浮標卡筍受損卡死！警方隨後在淡水河渡船頭高震東所有的舢舨夾層中，起獲了抽裝在柴油桶內的 20 公升純正濃縮原汁（比重瓶實測密度 1.25 g/cm³）。在比重瓶精確數據與舢舨原汁鐵證前，高震東痛哭認罪。",
