    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "中央印製廠新台幣千元券防偽特徵、純長纖維棉漿無螢光紙張特性、365nm 長波 UV 電子躍遷螢光、以及同版印刷偽造流水號鑑識。新台幣千元真鈔採用 100% 頂級純棉漿紙壓製，不含任何化學螢光增白劑，在 365nm 紫外線下呈暗黑吸光底色（死黑底色），僅局部防偽螢光纖維發出紅綠雙色螢光；而夜市偽鈔採用含有大量螢光增白劑之普通木漿道林紙，在 365nm 紫光下整張紙泛出刺眼奪目的亮藍白色螢光。同版假鈔流水號均為 FL882888UB，且外送員步行出入青草巷行人徒步區動線清晰可稽。",
    "curriculumMapping": "中央印製廠新台幣千元券防偽特徵、純長纖維棉漿無螢光紙張特性、365nm 長波 UV 電子躍遷螢光、以及同版印刷偽造流水號鑑識。新台幣千元真鈔採用 100% 頂級...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：新台幣千元或百元真鈔 1 張、365nm 紫外線小手電筒、白紙 1 張。原理：",
    "brief": "週六晚間八點半，艋舺廣州街觀光夜市人聲鼎沸。經營四十年古法炭烤胡椒餅的老攤主林金土，在短短二十分鐘內接連收到三張一千元大鈔。林金土忙著出爐找零未及細看，直到將鈔票放入錢盒摸到紙質光滑缺乏凹版印紋觸感，拿驗鈔筆一劃赫然變色，急忙高聲呼喊求助！",
    "storyCause": "週六晚間八點半，艋舺廣州街觀光夜市人聲鼎沸。經營四十年古法炭烤胡椒餅的老攤主林金土，在短短二十分鐘內接連收到三張一千元大鈔。林金土忙著出爐找零未及細看，直到將鈔票放入錢盒摸到紙質光滑缺乏凹版印紋觸感，拿驗鈔筆一劃赫然變色，急忙高聲呼喊求助！",
    "storyProcess": "在夜市徒步區巡守的都會調查員迅速趕抵胡椒餅攤位。剛才拿千元大鈔買胡椒餅找零的共有三人：身穿黑色連帽夾克的郭朝陽、背名牌包的上班族林詩涵、以及穿外送制服的機車外送員周文彬。周文彬表示：他在廣州街夜市外圍西園路口接到跑單客人要求代買炭火胡椒餅，客人塞給他一張千元大鈔，他便將機車停在外圍，步行走進攤位替客人購買，找零的 900 元全數放進隨身外送腰包，自己也是受害者；郭朝陽則自稱是成衣加工廠夜班兼職燙衣工，堅稱身上千元大鈔是工廠老闆剛發放的夜班加班現金津貼，自己絕不可能印假鈔。",
    "storyClimax": "都會調查員取出 365nm 紫外線鑑識手電筒，當場對涉案的三張千元大鈔與嫌疑人隨身錢包展開光學比對：在 365nm 紫外線照射下，真鈔因採用無螢光劑的頂級純長纖維棉紙，呈現沉穩深黑的吸光底色（死黑）；然而從郭朝陽手中收得的千元假鈔，整張紙立刻泛出刺眼奪目的強烈亮藍白色螢光！其顯然是由普通木漿紙印製，含有大量螢光增白劑。調查員進一步檢視假鈔流水號，號碼赫然為 FL882888UB；隨後在郭朝陽皮夾夾層中，起獲了另外六張同版印刷、流水號完全相同的 FL882888UB 假千元大鈔！此外，調查員調取西昌街青草巷口監視器，證實周文彬確實是將機車停妥於廣州街路邊後，徒步走進步行街買苦茶並在巷口被推車阻擋，其供詞完全屬實。在刺眼紫光亮藍螢光、完全相同之假鈔流水號 FL882888UB 與起獲贓款鐵證面前，郭朝陽無從狡辯，伏首認罪。",
