    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：方格筆記紙 1 張、剪刀、鉛筆。原理：",
    "brief": "剝皮寮歷史街區正在籌備「艋舺清代醫藥與青草傳奇特展」，展出由清代艋舺名醫黃玉階後人捐贈的一面光緒年間百年老藥籤樟木木刻板。然而昨夜閉館後，展間警報微響，館方文史員今晨發現木刻板表面的硃砂塗層竟遭人以化學藥劑局部擦拭，展台上遺留一張撕角黃紙，上面抄錄著五組看似毫無關聯的古怪中藥配方。據傳這面藥籤刻板內部封存著清代名醫治療艋舺瘟疫的失傳神效防疫古方！",
    "storyCause": "剝皮寮歷史街區正在籌備「艋舺清代醫藥與青草傳奇特展」，展出由清代艋舺名醫黃玉階後人捐贈的一面光緒年間百年老藥籤樟木木刻板。然而昨夜閉館後，展間警報微響，館方文史員今晨發現木刻板表面的硃砂塗層竟遭人以化學藥劑局部擦拭，展台上遺留一張撕角黃紙，上面抄錄著五組看似毫無關聯的古怪中藥配方。據傳這面藥籤刻板內部封存著清代名醫治療艋舺瘟疫的失傳神效防疫古方！",
    "storyProcess": "剝皮寮文教基金會董事長緊急委託都會調查員介入調查。文史展覽團隊內部有三人具有重大嫌疑：負責古籍文獻數位化的研究生林書瑋、私下經營民間偏方生技保健食品的業務副總趙成達、以及展覽館資深木器古董修復師傅蔡水旺。三人均在昨晚八點至九點留滯展館：林書瑋稱在掃描拓本；趙成達稱在參觀展場洽談文創授權；蔡師傅稱在檢查木刻板防蛀漆。現場遺留的那張黃紙抄錄著五味藥材：『木香』、『赤芍』、『甘草』、『白朮』、『澤瀉』，表面看似普通調和脾胃的中藥方，但文字排列字距寬度完全一致，且每行五字共排列成 25 字的方正字陣。",
    "storyClimax": "都會調查員將遺留的 5×5 黃紙字陣展開，結合國小社會課學到的艋舺傳統漢藥文化與自然科學中的植物屬性五行生剋展開縝密解密：字陣五行分別以『木香（木）、赤芍（火）、甘草（土）、白朮（金）、澤瀉（水）』為字首。依中醫五行相生順序：木生火、火生土、土生金、金生水、水生木，依序在 5×5 矩陣中按對角線交會軌跡提取對應文字，浮現出一句暗語：『福祥街三進中柱雀替斗栱下』！雀替與斗栱是清代閩南木造建築梁柱交接處的經典木構力學承重構件。都會調查員手持高位內視鏡手電筒，引領眾人來到剝皮寮展廳第三進最深處的支撐杉木大柱前。在柱頂精雕的「雀替」木構卡榫下方，赫然發現一處極其隱密的暗格！暗格內藏有一卷以油紙嚴密包裹的光緒九年名醫親筆手抄本《青草防癘驗方手札》。隨後，調查員利用便攜氣相層析儀檢測趙成達風衣袖口，測出與展台上殘留完全一致的乙酸乙酯（去光水主要溶劑）揮發氣體！趙成達意圖剽竊百年醫藥智慧的醜陋行徑大白於天下，在古蹟梁柱前低頭被捕，珍貴古籍回歸公眾文獻館藏。",
