    "scienceConcept": "天然植物花青素（Anthocyanin）酸鹼指示劑變色原理與土壤酸鹼度（pH 值）定性分析。紫甘藍（紫色高麗菜）汁液富含水溶性花青素，在強酸性（pH < 3）呈鮮紅色，在微酸性（pH 4~6）呈紫紅色或粉紅色，在中性（pH 7）呈紫色，在弱鹼性（pH 8~9）呈藍綠色，在強鹼性（pH > 10）呈黃綠色。不同地層之土壤浸出液酸鹼度各異，可作為地質來源追蹤之微物跡證。",
    "curriculumMapping": "天然植物花青素（Anthocyanin）酸鹼指示劑變色原理與土壤酸鹼度（pH 值）定性分析。紫甘藍（紫色高麗菜）汁液富含水溶性花青素，在強酸性（pH < 3）呈...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：紫高麗菜葉 1 片、熱水半杯、透明布丁杯 2 個、檸檬汁幾滴、小蘇打水幾滴。原理：",
    "brief": "淡水老街文史工作室昨夜舉辦淡水老明信片捐贈儀式，一位老華僑捐出了一枚極罕見、價值數十萬元的「1911年淡水神社落成紀念純銀紀念章」。然而深夜儀式結束鎖入玻璃展櫃後，今晨展櫃竟被撬開！而原本負責看管老屋的一隻深得街坊喜愛的吉祥物黑貓『阿巧』，今早從重建街山壁防空洞鑽出來時，爪子與雪白胸毛上竟沾染著大片鮮艷的磚紅色泥土，且嘴裡叼著一只原本包裹紀念章的紅絲絨布袋，紀念章本體卻下落不明！",
    "storyCause": "淡水老街文史工作室昨夜舉辦淡水老明信片捐贈儀式，一位老華僑捐出了一枚極罕見、價值數十萬元的「1911年淡水神社落成紀念純銀紀念章」。然而深夜儀式結束鎖入玻璃展櫃後，今晨展櫃竟被撬開！而原本負責看管老屋的一隻深得街坊喜愛的吉祥物黑貓『阿巧』，今早從重建街山壁防空洞鑽出來時，爪子與雪白胸毛上竟沾染著大片鮮艷的磚紅色泥土，且嘴裡叼著一只原本包裹紀念章的紅絲絨布袋，紀念章本體卻下落不明！",
    "storyProcess": "黑貓阿巧的異常動靜立刻引起了都會調查員的注意。防空洞連通多條分支坑道，深達數百公尺，若盲目開挖搜索無異大海撈針。案發時在文史工作室逗留的三位嫌疑人為：負責拍攝紀錄片的年輕導演林宇翔、老街陶藝工作室老闆兼登山嚮導洪大川、以及古董店年輕學徒葉家豪。林宇翔辯稱自己整夜在老街碼頭拍攝淡水日出縮時攝影；洪大川稱自己在陶藝拉胚窯爐前顧火；葉家豪則聲稱自己在店內擦拭老木櫃。三人靴子或手腳均沾有泥巴，均聲稱是走重建街石階時蹭到的普通黃土。",
    "storyClimax": "都會調查員就地取材，在老街果菜行買了一顆新鮮紫甘藍（紫包心菜），以溫水搗碎浸泡過濾出天然花青素紫甘藍紫色指示液，展開自然生活科學鑑識：都會調查員分別採集三處地點的土壤微量樣本並浸泡於純水中：樣品 A（老街步道普通砂質土）、樣品 B（陶藝拉胚黏土）、樣品 C（黑貓毛髮上沾附的磚紅色泥土）、以及嫌疑人靴底泥土。滴入紫甘藍指示劑後，樣品 A 呈藍綠色（弱鹼性 pH 8.2），樣品 B 呈灰紫色（中性 pH 7.0）；唯獨黑貓阿巧毛上的樣品 C，滴入紫甘藍液體後立刻轉變為鮮豔的「粉紅色」！證明該紅土呈現顯著的酸性反應（pH 5.0）。都會調查員指出：淡水全區只有崎仔頂防空洞深處大屯火山安山岩風化紅土層具有如此強烈的天然微酸性！而三名嫌疑人中，唯有陶藝老闆洪大川的工作登山鞋鞋底溝槽中，深嵌著一塊滴入紫甘藍同樣立刻變為粉紅色的強微酸性磚紅土，且鞋尖卡著黑貓阿巧脫落的細微黑毛！原來洪大川欠下陶藝窯廠巨額修繕款，昨夜撬開展櫃得手紀念章後，熟知防空洞地形的他原本想將銀章藏在防空洞深處暗道，卻在洞內驚遇黑貓阿巧撲抓，慌亂中將絲絨袋扯落被貓叼走，自己則倉皇逃出。在神奇的紫甘藍天然花青素酸鹼指示劑顯色鐵證下，洪大川面紅耳赤，只得乖乖帶領調查員進入防空洞深處暗隙起獲了深埋在酸性紅土中的百年純銀紀念章。",
