    "scienceConcept": "重力滑輪阻尼定時機械、冰塊吸熱融化延時釋放與常溫聲速（340 m/s）空間延遲。固態冰塊在常溫（25℃）下的融化熱與融化速率恆定，可作為天然延時配重；當冰塊完全融化成水排出容器，平衡配重消失觸發重力垂擺釋放擊鐘；在都會街廓中，聲波以約 340 m/s 傳播，依據不同街角聽到鐘聲的精確時間差可推導發聲源與監聽點的空間幾何位置。",
    "curriculumMapping": "重力滑輪阻尼定時機械、冰塊吸熱融化延時釋放與常溫聲速（340 m/s）空間延遲。固態冰塊在常溫（25℃）下的融化熱與融化速率恆定，可作為天然延時配重；當冰塊完全...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：免洗紙杯 2 個、棉線 1 條（約 3 公尺）、牙籤 2 截。原理：",
    "brief": "農曆十月青山王暗訪大拜拜前夕，青山宮執事堂正進行重要儀式演練。按照嚴格的祖規，二樓鐘樓的清代百年古青銅大鐘，必須在正午十二點整由大執事親自敲響以安撫地方地靈。然而，午夜零點零分整，萬籟俱寂的艋舺深夜，鐘樓大鐘竟然在無人值守的情況下突發『咚——』的一聲驚天動地的巨響！廟祝與巡邏員警驚駭地衝上二樓鐘樓，鐘樓鐵門鎖鏈完好無損，屋內空無一人，唯有厚重的青銅鐘錘在空中劇烈擺盪，鐘下地面殘留一大灘清澈水漬！而就在這聲鐘響的同一瞬間，相隔三條街外的西昌街青草行發生了一起三十萬元香油贊助金失竊案！",
    "storyCause": "農曆十月青山王暗訪大拜拜前夕，青山宮執事堂正進行重要儀式演練。按照嚴格的祖規，二樓鐘樓的清代百年古青銅大鐘，必須在正午十二點整由大執事親自敲響以安撫地方地靈。然而，午夜零點零分整，萬籟俱寂的艋舺深夜，鐘樓大鐘竟然在無人值守的情況下突發『咚——』的一聲驚天動地的巨響！廟祝與巡邏員警驚駭地衝上二樓鐘樓，鐘樓鐵門鎖鏈完好無損，屋內空無一人，唯有厚重的青銅鐘錘在空中劇烈擺盪，鐘下地面殘留一大灘清澈水漬！而就在這聲鐘響的同一瞬間，相隔三條街外的西昌街青草行發生了一起三十萬元香油贊助金失竊案！",
    "storyProcess": "這起神祕的「古鐘夜半自鳴案」震撼了整座艋舺老城。被懷疑盜取香油金的嫌犯共有四人：青山宮祭典組副組長陳天福、宮廟水電兼打更人張阿發、西昌街青草行掌櫃侄子林家寶、以及在廟口經營古董金飾店的郭文彬。林家寶在竊案發生時有三名鄰居作證看見他在青草行門口；而陳天福、張阿發與郭文彬三人，在午夜鐘聲敲響的瞬間，正巧站在廟口熱炒攤當著十幾名香客與巡警的面喝酒吃宵夜！『鐘聲響的時候大家都在廟口看手錶，我們都在喝酒，誰能跑上二樓敲鐘？』三人的不在場證明看似固若金湯。都會調查員受託登上鐘樓仔細勘查，發現青銅鐘錘後方的一根梁柱橫木上，有極細微的尼龍釣魚線勒痕，天花板通風天窗微開，地上那一灘水完全沒有任何糖分或化學成分，純為普通自來水。",
    "storyClimax": "都會調查員立即運用物理重力平衡與熱學融化速率揭開謎底：這是一場精心設計的『冰塊延時擊鐘物理機關』！兇手在昨日晚間十點借檢查鐘樓通風為由進入，利用一條極細的高拉力編結尼龍線，一端繫住十公斤重的大青銅鐘錘並將其向後拉緊至極限水平位置，尼龍線穿過天花板定滑輪，另一端繫著一個內置五公斤特大食用冰塊的漏水塑膠濾籃作為『阻尼配重』。深夜室溫約 24℃，冰塊吸熱融化（冰的熔化熱為 334 J/g），以每小時約 2.5 公斤的速度穩定均勻滴漏化水排出濾網。到了午夜零點整，五公斤冰塊恰好融化殆盡，配重重量大幅低於鐘錘拉力，尼龍線滑脫，沉重鐘錘在重力加速度下如拋物線般狠狠撞上青銅鐘體，發出午夜自鳴！這意味著機關布設時間為晚上十點至十點半之間！都會調查員調取青山宮廟埕水電表與巷口監視器，發現唯一在晚上十點提著保冷箱進入鐘樓的，正是水電兼打更人張阿發！更致命的是，都會調查員調取三條街外超商門口錄影的時間戳，聲波在空氣中傳播速度為 340 m/s，青草行監視器收錄到鐘聲的時間比青山宮廟口整整延遲了 1.2 秒（距離約 410 公尺），而張阿發利用這預先設定好的兩小時延時機關，在廟口假裝喝酒製造完美不在場證明，實則暗中夥同林家寶調包青草行保險箱現金。在冰塊融化速率物理實驗與鐘樓尼龍線微痕鐵證面前，張阿發防線徹底瓦解，低頭認罪並供出同夥。",
