    "scienceConcept": "固體傳聲共鳴率（Acoustic Resonance in Solids）與醫用聽診器聲學放大回音定位原理。聲波在緻密均勻固體（實心紅磚牆）中傳播時能量衰減快、反射回音頻率極高；若牆體內部存在空洞（空心暗格），敲擊時會在封閉空氣腔內激發特定低頻聲波共鳴（空氣柱共振）；利用金屬雙耳聽診器貼緊牆體，能將微弱的空洞回聲放大數十倍，精確定位隱藏暗門邊界。",
    "curriculumMapping": "固體傳聲共鳴率（Acoustic Resonance in Solids）與醫用聽診器聲學放大回音定位原理。聲波在緻密均勻固體（實心紅磚牆）中傳播時能量衰減快、...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：小塑膠漏斗 1 個、透明塑膠軟管 1 截（約 40 公分）、氣球皮 1 片、橡皮筋 1 條。原理：",
    "brief": "淡水滬尾偕醫館正籌備馬偕博士逝世週年特展，由加拿大馬偕家族後代跨海借展一具馬偕博士當年親手使用過的骨董雙耳木質聽診器與拔牙鉗。昨夜閉館盤點時，導覽志工赫然發現：原置於玻璃展示櫃內的一枚由清光緒皇帝為嘉獎馬偕救護中法戰爭清軍傷兵所特賜的「提督軍功御賜銀牌」，竟不翼而飛！展廳門窗防盜鎖鏈皆未被破壞，展廳內部彷彿有隱形暗門一般，珍貴銀牌離奇失蹤！",
    "storyCause": "淡水滬尾偕醫館正籌備馬偕博士逝世週年特展，由加拿大馬偕家族後代跨海借展一具馬偕博士當年親手使用過的骨董雙耳木質聽診器與拔牙鉗。昨夜閉館盤點時，導覽志工赫然發現：原置於玻璃展示櫃內的一枚由清光緒皇帝為嘉獎馬偕救護中法戰爭清軍傷兵所特賜的「提督軍功御賜銀牌」，竟不翼而飛！展廳門窗防盜鎖鏈皆未被破壞，展廳內部彷彿有隱形暗門一般，珍貴銀牌離奇失蹤！",
    "storyProcess": "淡水文資保存小組連夜委請都會調查員趕抵現場。現場有三名嫌疑人：負責醫館展場水電維修的技工莊培元、借展單位的加拿大華裔文史研究員戴維斯（Davis）、以及經常在醫館擔任義務導覽的退休教師廖淑華。三人均聲稱自己在案發時段未曾靠近展櫃。莊培元稱自己在後院更換日光燈管；戴維斯稱自己在長老教會圖書館查閱馬偕日記；廖老師稱自己在前堂擦拭老管風琴。都會調查員仔細勘查展間，發現展櫃旁的清代紅磚壁爐後方牆面，有幾處極微小的磚粉脫落痕跡，且壁爐基座的地板紅磚有些微肉眼難辨的水平位移，但整面牆看似平整嚴密，徒手推敲根本無法分辨內部虛實。",
    "storyClimax": "都會調查員靈機一動，向館方借用特展中那具保存完好、馬偕博士當年生前親手使用的「骨董雙耳聲學聽診器」！調查員戴上聽診器，將金屬集音聽頭緊緊貼住紅磚牆面，另一手持橡膠小槌輕輕沿著牆體表面以 10 公分間距進行矩陣敲擊。這是一場教科書級的物理聲學探測：敲擊實心磚牆時，聽診器傳來的是清脆短促、頻率極高且迅速衰減的「篤篤」悶音；然而當敲擊點移至壁爐左側第三排紅磚時，聽診器內瞬間傳來清晰深沉、伴隨明顯低頻嗡鳴共振的「空洞回響」（空氣柱共鳴頻率約 250Hz）！都會調查員循著聲音衰減的邊界在牆上劃出一塊精確的 40×40 公分正方形區域。調查員伸手握住壁爐上方的清代煤油燈座向順時針旋轉 90 度，只聽清脆的金屬彈簧卡榫聲響起，那塊看似天衣無縫的紅磚牆竟然向內彈開，露出一個隱密的清代藥品暗格！而那枚失竊的提督軍功御賜銀牌正藏在暗格深處，旁邊還放著一支沾有新鮮紅磚灰粉的水電螺絲起子！調查員轉身比對工具型號，與莊培元隨身水電工具腰帶上的起子完全一致；且其手腕手錶錶帶夾縫中，檢出與暗格內部清代蜘蛛網及石灰粉完全吻合的微物跡證。原來莊培元在維修管線時偶然發現了暗格機關，心生貪念企圖將國寶級銀牌偷藏於牆內，待風聲過後再取走變賣。在馬偕博士百年聽診器重現神威的聲學共振破案奇蹟面前，莊培元無可辯解，當場下跪認罪。",
