    "storyCause": "台北市文化局在進行北門周邊景觀綠美化與光環境營造工程時，工程團隊在北門城台下方的清代排水涵洞石縫中，意外清理出一份清末台灣巡撫劉銘傳防衛台北城的秘密遺稿抄本。遺稿記載：中法戰爭後，清廷曾在北門承恩門正上方石額的某個特定『日影投射幾何焦點』地底，埋設了一個裝有建城原始銅版全圖與鎮印的青銅地宮寶盒！遺稿寫道：『秋分日影切石額，午正三刻印黃土』。然而，昨夜北門廣場夜深人靜之際，有人利用高精度無人機與雷射標線器在廣場石板地上鬼祟測量並企圖以微型地鑽開鑿石板！",
