    "scienceConcept": "天然藍靛（Indigo）氧化還原化學反應與維生素 C（抗壞血酸）還原脫色特性。天然藍染使用『馬藍』植物色素，在染缸中經還原劑作用轉為無色可溶之『白靛』（Leuco-indigo），浸染布料後接觸空氣中的氧氣，氧化轉變為不溶於水之鮮豔深藍色靛藍；若遭過氧化氫（雙氧水）或強氧化漂白劑破壞會褪色發白，而利用弱酸性抗壞血酸（維生素 C）還原液可逆轉特定過度氧化沉澱，鑑別出人為破壞之化學痕跡。",
