    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：透明水杯裝半杯水、家用醫用優碘 3 滴、發泡錠碎屑（或維他命 C 飲料幾滴）。原理：",
    "brief": "台北時裝週「台灣傳統文創大展」開幕前夕，迪化街百年布莊「錦豐染織」準備參展的鎮店之寶——一幅耗時半年以古法馬藍純手工染製、價值逾五十萬元的特大國寶級藍染壁毯《大稻埕千帆圖》，今晨在天井晾曬架上被發現竟遭人潑灑不明透明液體，原本深邃典雅的靛藍色江面圖案，大面積嚴重褪色變白發黃，形同全毀！",
    "storyCause": "台北時裝週「台灣傳統文創大展」開幕前夕，迪化街百年布莊「錦豐染織」準備參展的鎮店之寶——一幅耗時半年以古法馬藍純手工染製、價值逾五十萬元的特大國寶級藍染壁毯《大稻埕千帆圖》，今晨在天井晾曬架上被發現竟遭人潑灑不明透明液體，原本深邃典雅的靛藍色江面圖案，大面積嚴重褪色變白發黃，形同全毀！",
    "storyProcess": "老布莊掌門人痛心疾首，都會調查員接獲緊急通報火速趕往現場。展覽評審將在今天下午三點進行實地驗收，若無法在數小時內查明原因並採取補救，老店不僅失去參展資格，商譽更將毀於一旦！現場有三名涉案人員：布莊首席染整師傅吳志榮、前來洽談布料代理的快時尚服飾品牌採購副總高偉倫、以及老掌櫃的小兒子兼文創設計師陳思翰。三人各執一詞：吳師傅聲稱自己昨晚十點鎖門離開前壁毯完好如初；高偉倫表示自己只是早上依約來參觀；陳思翰則堅稱自己在二樓設計室趕工繪製宣傳手冊。都會調查員俯身勘驗壁毯受損區域，發現布面纖維並未被強酸炭化燒焦，但散發出一股淡淡的特殊藥水味，且晾曬架下方有一只被丟棄的眼藥水滴管塑料瓶。",
    "storyClimax": "都會調查員立即運用 108 課綱國中理化的『氧化還原反應』展開破案鑑識：調查員取下一小段褪色布條進行定性分析，滴入微量碘化鉀澱粉試劑，試劑立刻由透明轉為深深藍色！這證明潑灑在壁毯上的並非普通自來水，而是高濃度的過氧化氫（雙氧水）氧化漂白劑！雙氧水強烈奪取電子，破壞了馬藍靛藍色素的共軛雙鍵發色團結構，使其被迫氧化褪色。緊接著，調查員出示了一手絕妙的化學還原修復技巧：調查員調配了一盆精準比例的天然弱酸性抗壞血酸（維生素 C）與微量保險粉（連二亞硫酸鈉）溫水還原溶液，以極細噴霧均勻噴灑在褪色區域。奇蹟發生了——在維生素 C 的溫和供電子還原作用下，被氧化的中間產物迅速逆向還原為淡黃色白靛，隨後接觸空氣中的氧氣再度自然氧化，原本發白的千帆圖案竟以肉眼可見的速度重新凝聚出層次豐富的深藍色靛藍，壁毯竟被神乎其技地救回了八成！與此同時，都會調查員以紫外螢光燈照射三名嫌疑人的雙手，快時尚副總高偉倫的雙手在燈下呈現明顯的皮膚角質層氧化微白斑痕（雙氧水接觸皮膚導致的蛋白質變性泛白）！搜查其公事包，起獲了一瓶含有 30% 工業級過氧化氫的高濃度隱形眼鏡殺菌瓶。原來高偉倫代表的跨國快時尚公司企圖以低價收購錦豐布莊的傳統專利，刻意破壞參展壁毯逼迫老布莊在違約賠償重壓下屈服簽署不平等代理合約。在無可辯駁的氧化還原化學鑑識與人體微物跡證面前，高偉倫狼狽不堪，當場被警方依毀損罪帶回警局，老布莊的百年名譽與參展資格化險為夷。",
