    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "維吉尼亞多表替換密碼（Vigenère Cipher）與捷運車站官方編號金鑰對照解碼。維吉尼亞密碼透過一個特定長度的金鑰單字（Keyphrase），在 26×26 的字母方陣（Tabula Recta）中逐字進行多重位移置換；相較於簡單單表替換，多表替換能徹底平滑單一字母的出現頻率；本案巧妙以台北捷運淡水信義線官方車站編號（如 R10 台北車站、R11 中山、R12 雙連）作為數字/字母循環位移金鑰。",
    "curriculumMapping": "維吉尼亞多表替換密碼（Vigenère Cipher）與捷運車站官方編號金鑰對照解碼。維吉尼亞密碼透過一個特定長度的金鑰單字（Keyphrase），在 26×2...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：長條紙條 2 張（剪成寬 2 公分紙尺）、鉛筆。原理：",
    "brief": "中山地下書街正舉辦「台灣珍稀古籍與文獻手稿展」，展出一本由日治時期台灣文人賴和友人手抄、極為珍貴的 1930 年代古典詩文孤本手札《島嶼星火》。然而在深夜清場閉館前半小時，值班書店員驚恐發現：展示櫥窗後方的隱形鋼化玻璃鎖被開啟，手札本體被掉包成一本外皮一模一樣、內頁卻全是亂碼英文字母與數字排列的假手抄本！假書最後一頁夾著一張燙金書籤，上面印著一串長達 30 字的維吉尼亞加密密文與一列神秘的英文字軌：『KEY: T-R-A-I-N』！",
    "storyCause": "中山地下書街正舉辦「台灣珍稀古籍與文獻手稿展」，展出一本由日治時期台灣文人賴和友人手抄、極為珍貴的 1930 年代古典詩文孤本手札《島嶼星火》。然而在深夜清場閉館前半小時，值班書店員驚恐發現：展示櫥窗後方的隱形鋼化玻璃鎖被開啟，手札本體被掉包成一本外皮一模一樣、內頁卻全是亂碼英文字母與數字排列的假手抄本！假書最後一頁夾著一張燙金書籤，上面印著一串長達 30 字的維吉尼亞加密密文與一列神秘的英文字軌：『KEY: T-R-A-I-N』！",
    "storyProcess": "展場隨即封鎖，都會調查員趕抵地下書街現場。由於距離捷運末班車停駛與地下街全面斷電僅剩最後 40 分鐘，若不能在斷電前破解密碼尋回手札，嫌犯將趁深夜清潔工換班混出站外。現場排查出三名在熄燈前逗留在古籍展區附近的嫌疑人：專門收購二手古籍的跳蚤市場書商周坤成、歷史研究所文獻修復研究生徐珮玲、以及地下街夜間水電巡修工陳國華。周坤成聲稱自己剛在二手書店淘到幾本老食譜；徐珮玲堅稱自己在用平板校對論文出處；陳國華則稱自己在檢查地下消火栓水壓。三人都堅稱自己從未碰過櫥窗玻璃，且身上都沒有藏匿手札。那串神秘密文『W-K-S-P-L-Z-O-U-D...』成為破案唯一的生機。",
    "storyClimax": "都會調查員立即運用資訊科技與古典密碼學的『維吉尼亞多表替換方陣』展開急速心算解碼：密文開頭為『W-K-S-P-L』，金鑰提示為『T-R-A-I-N』（火車），暗喻中山地下街前身為台鐵淡水線鐵道！都會調查員在筆記本上繪製 26×26 的維吉尼亞密碼表（Tabula Recta），將密文字母與金鑰字母進行反向位移查表：第一字密文 W 與金鑰 T（位移 19），解密得出字母『D』；第二字 K 與金鑰 R（位移 17），解密得出『O』；第三字 S 與金鑰 A（位移 0），解密得出『S』；第四字 P 與金鑰 I（位移 8），解密得出『H』；第五字 L 與金鑰 N（位移 13），解密得出『Y』⋯⋯逐步解密出完整英文句子：『DOWN STATION STORAGE R12 HYDRANT』（雙連站置物箱消火栓）！『R12』正是中山地下街北端終點——雙連捷運站的官方代碼！都會調查員拔足狂奔，沿著地下街疾步衝向雙連站方向，在 R12 出口旁的 4 號地下消防栓檢修箱夾層內，赫然起獲了被用塑膠密封袋嚴密包裹的珍貴《島嶼星火》手札孤本！與此同時，調閱該消防栓檢修紀錄，唯一持有該箱鑰匙且在案發前十分鐘剛簽名巡檢的，正是水電工陳國華！搜查陳國華工具推車底部，搜出了被拆卸的展示櫃磁簧遙控開關。原來陳國華受境外骨董走私買家以五十萬元利誘，利用熟知地下街各消防栓暗箱位置監守自盜，企圖透過加密書籤將取貨地點通知同夥接應。在維吉尼亞密碼破譯與雙連站消防栓物證面前，陳國華無從推諉，雙手抱頭當場認罪。",
