    "scienceConcept": "秋分太陽方位角與赤緯高度角幾何方程式、相似三角形定理與漏窗日影投影。秋分當日太陽直射地球赤道（赤緯 δ = 0°），正午太陽高度角等於 90° 減去當地地理緯度（板橋北緯約 25.0°，秋分正午高度角約 65.0°）；特定的漏窗幾何花紋在特定時刻所投射於對面石壁之日影頂點位置具嚴密時空唯一性。",
    "curriculumMapping": "秋分太陽方位角與赤緯高度角幾何方程式、相似三角形定理與漏窗日影投影。秋分當日太陽直射地球赤道（赤緯 δ = 0°），正午太陽高度角等於 90° 減去當地地理緯度...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：小紙盒 1 個、美工刀、手電筒（或手機閃光燈）。原理：",
    "brief": "時值秋分之日，板橋林家花園方鑑齋正舉辦「林本源家族清代文獻特展」。展覽最核心之展品為林家先祖林維源當年主持台灣建省善後時所使用的「金絲楠木雲龍刻紋官印匣」，匣內盛裝著清代板橋拓墾與大漢溪渡船水權合約金箔冊。然而下午一點整，展覽工作人員赫然發現：原置於方鑑齋水榭中央紅木案几上的金絲楠木印匣竟消失不見，而方鑑齋對面戲台後方的青磚基座上，多了一道疑似用鑿子強行撬動留下的新鮮石灰刮痕！",
    "storyCause": "時值秋分之日，板橋林家花園方鑑齋正舉辦「林本源家族清代文獻特展」。展覽最核心之展品為林家先祖林維源當年主持台灣建省善後時所使用的「金絲楠木雲龍刻紋官印匣」，匣內盛裝著清代板橋拓墾與大漢溪渡船水權合約金箔冊。然而下午一點整，展覽工作人員赫然發現：原置於方鑑齋水榭中央紅木案几上的金絲楠木印匣竟消失不見，而方鑑齋對面戲台後方的青磚基座上，多了一道疑似用鑿子強行撬動留下的新鮮石灰刮痕！",
    "storyProcess": "林園管理處隨即封鎖各進隘門出口，都會調查員受託迅速趕抵水院現場。當時在園內方鑑齋水院停留的嫌疑人有三位：專研台灣古蹟雕刻的文史修復師唐啟榮、林家宗親會總幹事林伯勳（近年因家族土地爭議與基金會不睦）、以及前來參觀並在迴廊架設專業縮時攝影機的建築系研究生周冠廷。唐啟榮聲稱自己當時正在來青閣白牆下量測漏窗尺寸；林伯勳堅稱自己一直在汲古書屋翻閱族譜；周冠廷則表示自己在拍攝秋分水池倒影的光影變化。方鑑齋長廊設有多面造型各異的清代花磚漏窗（福壽雙全蝠紋漏窗、定靜安慮花瓶漏窗等），秋分正午的陽光透過漏窗，在對面石壁上投射出繁複交錯的明暗光影。",
    "storyClimax": "都會調查員立即運用 108 課綱地球科學與國中幾何的『太陽投影與相似三角形』展開推導：現場在戲台基座下方發現一張被風吹落的便條紙，上面抄錄著一句林家先祖的古訓詩句：『秋分日正蝙蝠飛，影指水底真龍歸』！這是一句時空投影定位密碼！秋分正午 12 點整，太陽赤緯為 0 度，板橋當地正午太陽高度角精確為 65.0 度，方位角正南方（180°）。方鑑齋長廊上方那扇精雕細琢的『倒吊五蝠（福）磚雕漏窗』，距離水池石壁水平距離為 4.8 公尺、距水面高度為 2.24 公尺。透過正切函數 tan(65°) ≈ 2.144 或相似三角形高影比計算，五蝠漏窗中央最長一隻蝙蝠石雕鼻尖的日影焦點，在秋分正午十二點整，恰恰不偏不倚精準投射在方鑑齋水池正中央戲台水榭最下層的一塊刻有鯉魚紋樣的親水基石上！都會調查員率領潛水員探入清澈的水池基石下方，果然在鯉魚基石凹槽暗格中，起獲了被防水油布緊密包裹的金絲楠木官印匣！與此同時，都會調查員調取周冠廷相機的縮時高解析影片逐格放大比對：在正午 11:58 至 12:05 之間，林伯勳藉口上廁所離開書屋，正是趁著陽光陰影精準對齊水池鯉魚石的一瞬間，利用特製帶磁鐵伸縮長竿探入池底取出印匣企圖藏匿！而在林伯勳的外套暗袋中，搜出了一根沾有水池藻類綠泥的伸縮碳纖維竿。在精密太陽幾何光影定位與縮時錄影鐵證面前，林伯勳羞愧萬分，低頭認罪，國寶級文物回歸林園珍藏。",
