    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "液體受熱體積膨脹熱學原理（體膨脹係數 ΔV = V0 × β × ΔT）、毛細管截面阻滯與高海拔大氣壓對沸點之微量影響。水銀（汞）具有高度均勻之體膨脹係數；在水銀柱毛細管特定刻度處若以微量耐高溫氟素油脂或微型阻尼栓刻意塗抹，可使水銀柱在受熱上升至特定溫度時停滯阻卡，製造水溫偏低之虛假讀數詐術。",
    "curriculumMapping": "液體受熱體積膨脹熱學原理（體膨脹係數 ΔV = V0 × β × ΔT）、毛細管截面阻滯與高海拔大氣壓對沸點之微量影響。水銀（汞）具有高度均勻之體膨脹係數；在水...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：小寶特瓶 1 個裝滿加紅墨水的水、細透明吸管 1 支、黏土 1 塊。原理：",
    "brief": "北投溫泉飯店業者近期正與溫泉水供應公司洽談年度白磺泉採購續約水費。合約規定：供應水溫若持續低於標準保證水溫 85℃，溫泉水公司每季需補償退還飯店業者高達上百萬元的違約賠償金。昨晨進行官方聯合定期水溫驗收時，公證檢驗員在硫磺谷中央集水槽使用高精度長管水銀工業溫度計測量，水銀柱竟離奇卡在 74℃ 紋絲不動，水槽周圍白煙滾滾熱氣灼人，水溫數值卻明顯反常！溫泉水公司面臨巨額賠償危機，負責人痛斥有人蓄意搞鬼！",
    "storyCause": "北投溫泉飯店業者近期正與溫泉水供應公司洽談年度白磺泉採購續約水費。合約規定：供應水溫若持續低於標準保證水溫 85℃，溫泉水公司每季需補償退還飯店業者高達上百萬元的違約賠償金。昨晨進行官方聯合定期水溫驗收時，公證檢驗員在硫磺谷中央集水槽使用高精度長管水銀工業溫度計測量，水銀柱竟離奇卡在 74℃ 紋絲不動，水槽周圍白煙滾滾熱氣灼人，水溫數值卻明顯反常！溫泉水公司面臨巨額賠償危機，負責人痛斥有人蓄意搞鬼！",
    "storyProcess": "雙方爭執不下引發肢體衝突，都會調查員接獲委託迅速趕抵硫磺谷現場。涉嫌動手腳的三位關鍵關係人為：代表八家五星級溫泉飯店聯合採購委員會的總稽核彭振剛、負責現場閥門管線巡檢的溫泉水公司資深技工陳金水、以及受委託出具水溫公證報告的第三方檢驗所工程師蘇家瑋。彭振剛堅稱數值是公證儀器測得的，白紙黑字不容賴帳；陳金水聲稱自己清晨剛檢修過蒸氣噴嘴，噴氣壓力充沛絕不可能只有 74℃；蘇家瑋則表示溫度計是從檢驗所密封防震箱拿出來的標準件，絕無拆封。都會調查員觀察滾燙沸騰、劇烈翻滾的白磺溫泉池，周圍岩石硫磺結晶明顯，地熱蒸氣噴發聲如雷貫耳，直覺判斷實際水溫絕對遠高於 74℃。",
    "storyClimax": "都會調查員立即運用國小高年級與國中自然科學的『熱脹冷縮與沸點物理』展開驗證：調查員首先取出隨身攜帶的校準紅外線熱成像儀，遠程照射集水槽噴湧核心，屏幕上立刻顯示出高達 96.5℃ 的超高溫紅紫色熱斑！接著，調查員在眾人面前將這支爭議的長管水銀溫度計浸入滾燙溫泉中：水銀柱迅速從室溫 25℃ 向上飆升，然而在到達 74℃ 刻度線時，水銀液柱頂端突然出現極為詭異的扁平鈍化，隨後如同遇到無形屏障般徹底卡住！都會調查員拿出手持 50 倍精密光學放大鏡對準 74℃ 刻度處的玻璃毛細管細看——在極細的毛細管壁內側，竟被人以顯微注射針頭注入了一微滴微米級透明高黏度耐高溫氟素矽油！矽油黏度極高且耐溫達 250℃，當水銀柱膨脹推擠至該點時，毛細管表面張力被劇烈改變形成強大逆向阻尼，死死鎖住了水銀柱的膨脹行程！調查員隨即搜查現場人員背包，在飯店總稽核彭振剛的保溫杯底座暗格中，搜出了極細的 0.1mm 顯微注射針頭與剩餘的氟素油脂瓶。原來彭振剛收受了飯店業者的非法高額績效回扣，企圖透過竄改公證溫度計偽造水溫不足，藉此勒索溫泉水公司每季 200 萬元的合約差價。在耐高溫矽油與毛細管阻尼物理破綻面前，彭振剛臉色發白，當場被警方依背信與詐欺罪嫌移送法辦。",
