    "curriculumMapping": "固體壓強公式（P = F / A）、土壤抗剪強度極限與人體步幅力學（Stride Length Mechanics）。在雨後飽和含水之軟黏火山灰土壤上行走時，腳...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：黏土（或油土）1 塊搓圓壓平、鉛筆 1 支。原理：",
    "brief": "竹子湖花卉產銷班歷時三年、耗資數十萬元從荷蘭引進並成功改良適應台灣氣候的極珍貴新品種——「七彩幻影火山紫」特級繡球花種苗母株共計六株，原本預計於明日陽明山繡球花季開幕式上公開亮相。然而昨夜一場突發雷陣雨過後，花農清晨巡田赫然發現：育苗溫室的鐵絲網遭人剪破，六株價值連城的繡球花母株連根被挖走，花泥地上遺留著一串雨夜泥濘深腳印！",
    "storyCause": "竹子湖花卉產銷班歷時三年、耗資數十萬元從荷蘭引進並成功改良適應台灣氣候的極珍貴新品種——「七彩幻影火山紫」特級繡球花種苗母株共計六株，原本預計於明日陽明山繡球花季開幕式上公開亮相。然而昨夜一場突發雷陣雨過後，花農清晨巡田赫然發現：育苗溫室的鐵絲網遭人剪破，六株價值連城的繡球花母株連根被挖走，花泥地上遺留著一串雨夜泥濘深腳印！",
    "storyProcess": "花卉產銷班班長心急如焚通報都會調查員到場協助。竊賊作案時間推斷在昨夜雷陣雨停歇的凌晨一點至兩點之間。現場嫌疑人有三位：隔壁競爭花田的青年農場主廖家豪、在水車寮步道旁經營景觀土雞城的廚師郭大富、以及一名聲稱冒雨在竹子湖夜觀台北樹蛙的大學昆蟲系碩士生許庭宇。廖家豪堅稱自己昨晚一直在家看花卉育苗 YouTube 直播；郭大富聲稱自己在廚房熬煮老母雞高湯；許庭宇則表示自己在水溝邊錄青蛙叫聲。都會調查員實地勘查泥地上的鞋印：這串鞋印共有十四枚，紋路為標準的知名品牌雙層防滑雨鞋底紋，鞋印痕跡自溫室直通步道後方的竹林暗道。",
    "storyClimax": "都會調查員立即運用 108 課綱自然力學與步幅方程式進行精密測量與計算：鞋印長度為 27.5 公分（換算為歐規 43 號鞋），但下陷深度卻極不尋常地深達 6.2 公分！都會調查員當場以彈簧壓強計測試田間泥土的極限抗剪承載力：要使 43 號鞋底在飽和火山泥中下陷達 6.2 公分，行走者施加的總重量必須達到 95 至 100 公斤以上！而在三名嫌疑人中，碩士生許庭宇身材瘦削體重僅 58 公斤，青年農友廖家豪體重約 68 公斤；唯有土雞城廚師郭大富體重達 92 公斤，若再加上六株帶土花苗的重量（約 8 公斤），正好完美吻合 100 公斤的力學下沉極限！更致命的破綻在於「步幅與受力向量」：泥印呈現足跟深陷達 6.5 公分、腳尖處有向後劇烈蹬踏的泥土飛濺痕跡，步幅由前進時的 75 公分突然縮短為 50 公分，這是人體肩部負重物體前行時典型的力學重力代償特徵！都會調查員循著步幅軌跡穿過竹林，直接來到郭大富土雞城後院的廢棄冷藏庫前。在冷藏庫暗格內，搜出了被小心翼翼浸泡在營養液中的六株被盜特級繡球花母株！與此同時，搜查郭大富的雨鞋，鞋底花紋與田埂泥印分毫不差，且鞋縫卡著溫室剪斷的鍍鋅鐵絲殘渣。原來郭大富私下與外縣市花商簽下合約，企圖竊取獨家母株連夜轉賣牟利。在精密的物理壓強計算與步幅力學鐵證面前，郭大富無法抵賴，只得伏首認罪。",
