    "scienceConcept": "橢圓幾何反射聚焦原理（Whispering Gallery Effect，耳語廊效應）與聲波反射定律。橢圓曲線具有兩個幾何幾何焦點（F1 與 F2）；從其中一個焦點發出的任何聲波，無論朝向橢圓弧形石壁的何種角度射出，經光滑堅硬壁面反射後，都會以相同的路徑長度同時精準聚焦匯聚於另一個焦點；在該焦點處能清晰聽到微弱竊竊私語，而在橢圓中心其他位置則完全聽不清楚。",
    "curriculumMapping": "橢圓幾何反射聚焦原理（Whispering Gallery Effect，耳語廊效應）與聲波反射定律。橢圓曲線具有兩個幾何幾何焦點（F1 與 F2）；從其中一個...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：大不鏽鋼調調理碗 2 個、鬧鐘（或手機秒針滴答聲音訊）。原理：",
    "brief": "北投溫泉博物館閉館前夕，文博安保團隊正在進行一項機密特展的安防佈置：由日本友好城市借展展示的一只 1913 年公共浴場落成紀念「大正天皇御賜白金彩繪溫泉懷錶」，暫存於大浴池中央的強化玻璃密碼展示櫃中。該展示櫃的電子密碼每晚由兩位資深主管各自保管半截密碼，並於大浴池邊緣以極低聲交頭接耳完成每日交接確認。然而今早開館時，展示櫃竟被以完全正確的八位數密碼開啟，價值上百萬元的落成懷錶不翼而飛！",
    "storyCause": "北投溫泉博物館閉館前夕，文博安保團隊正在進行一項機密特展的安防佈置：由日本友好城市借展展示的一只 1913 年公共浴場落成紀念「大正天皇御賜白金彩繪溫泉懷錶」，暫存於大浴池中央的強化玻璃密碼展示櫃中。該展示櫃的電子密碼每晚由兩位資深主管各自保管半截密碼，並於大浴池邊緣以極低聲交頭接耳完成每日交接確認。然而今早開館時，展示櫃竟被以完全正確的八位數密碼開啟，價值上百萬元的落成懷錶不翼而飛！",
    "storyProcess": "全館封鎖，都會調查員受命進行競速破案。兩位保管密碼的主管（館長高慶華、展務組長鄭雅玲）堅決表示：昨晚交接密碼時，兩人特意站在大浴池大廳最偏僻的西側弧形拱壁下，以蚊子般的微弱氣音（音量低於 30 分貝）耳語交代密碼，當時大廳中央空無一人，絕不可能有人近距離竊聽！現場被列入清查的涉案人員有三位：昨晚在大浴池走廊擦拭彩繪玻璃的清潔工周阿水、在展廳調校投射燈光角度的燈光技師陳信良、以及常在館內練習古典小提琴的音樂學院學生徐若薇。三人均否認靠近過西側拱壁。周阿水稱自己一直在洗手台洗拖把；陳信良堅稱自己在東側弧形立柱後方收電線；徐若薇則表示自己在二樓榻榻米大廳收拾樂譜。監控畫面證實，兩名主管交接密碼時，陳信良確實站在相距長達 18 公尺的東側圓拱石柱下，距離遠超一般耳語傳播極限！",
    "storyClimax": "都會調查員立即運用建築聲學與高中數學的『橢圓雙焦點幾何反射原理』解密！調查員調閱北投公共浴場 1913 年的原始建築工程藍圖：這座宏偉的仿羅馬大浴池大廳，其天花板拱頂與兩側弧形圍牆，其平面曲線並非標準圓形，而是一座經過精密數學設計的標準『橢圓幾何曲面』！長軸長度為 24 公尺，短軸為 16 公尺。依橢圓幾何公式 c² = a² - b²（c = √(12² - 8²) ≈ 8.94 公尺），計算得出大廳的兩個幾何焦點 F1 與 F2，恰恰不偏不倚坐落於大浴池西側第三圓拱柱下與『東側弧形立柱陰影處』！都會調查員站在主管耳語的西側焦點 F1，以極微弱氣音念出一段數字，站在 18 公尺外東側焦點 F2 的警官竟然如同戴著入耳式耳機一般，一清二楚地聽到了每一個字音！聲波經光滑弧形磁磚與拱頂多次全反射，能量在 F2 點瞬間全數同相疊加聚焦！而昨晚站在東側焦點 F2 的人，正是燈光技師陳信良！都會調查員立即搜查陳信良的燈具金屬工具箱，在一個偽裝成鹵素燈泡的防震海綿盒內，赫然起獲了被盜的大正落成白金彩繪懷錶！更致命的是，陳信良的手機記事本中，第一條未命名的備忘錄正是昨晚兩位主管耳語交接的八位數密碼！在無懈可擊的橢圓雙焦點聲學聚焦物理原理面前，陳信良無言以對，只得將懷錶交出認罪。",
