    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：透明玻璃小杯 1 個、生鏽鐵釘 1 根（或生鏽硬幣）、新鮮檸檬汁半杯。原理：",
    "brief": "雙北國際觀光溫泉季即將登場前夕，地熱谷公園巡園員清晨進行步道安全檢查時，驚駭發現：核心湧泉口正上方、保護遊客免於跌入 95℃ 沸泉的關鍵金屬加固護欄支柱，其底部四顆厚重的不鏽鋼地腳螺栓竟然嚴重斷裂腐蝕！斷裂處金屬呈現蜂窩狀孔洞並附著著一層詭異的墨綠色結晶，整面護欄搖搖欲墜。若非巡園員及時拉起封鎖線，當日湧入的數百名外籍觀光客一旦倚靠護欄，將發生墜入滾燙沸騰強酸池的災難性重大傷亡！",
    "storyCause": "雙北國際觀光溫泉季即將登場前夕，地熱谷公園巡園員清晨進行步道安全檢查時，驚駭發現：核心湧泉口正上方、保護遊客免於跌入 95℃ 沸泉的關鍵金屬加固護欄支柱，其底部四顆厚重的不鏽鋼地腳螺栓竟然嚴重斷裂腐蝕！斷裂處金屬呈現蜂窩狀孔洞並附著著一層詭異的墨綠色結晶，整面護欄搖搖欲墜。若非巡園員及時拉起封鎖線，當日湧入的數百名外籍觀光客一旦倚靠護欄，將發生墜入滾燙沸騰強酸池的災難性重大傷亡！",
    "storyProcess": "這起惡性公共安全破壞案震驚了雙北市府，都會調查員受命火速馳援現場。鑑識人員初步勘查，斷裂的金屬螺栓斷口並非機械外力鋸斷，而是遭受強烈化學酸液集中腐蝕溶解穿孔！涉嫌蓄意破壞護欄的嫌疑人有三位：承攬地熱谷護欄防蝕塗裝工程的營造包商郭富榮、長期在地熱谷周邊非法擺攤販售號稱『能量北投石手鍊』的私梟林春生、以及曾因向市府投訴溫泉氣味擾民遭駁回的鄰近別墅業主沈伯毅。郭富榮堅稱自己使用的是最高等級 316 醫療級防腐蝕不鏽鋼螺栓，絕不可能幾個月就腐蝕；林春生辯稱自己昨晚只是在步道外圍乘涼；沈伯毅則表示自己在自家別墅露台喝茶。都會調查員觀察護欄基座，發現斷裂螺栓周圍的木棧板有局部被重酸灼燒變黑的滴漏痕跡，且旁邊散落著一只耐酸聚乙烯（HDPE）塑膠瓶蓋。",
    "storyClimax": "都會調查員立即運用 108 課綱國中理化的『酸鹼鹽與金屬置換反應』展開鑑識化驗：調查員刮取斷裂螺栓表面的墨綠色結晶溶於蒸餾水，滴入幾滴『赤血鹽（鐵氰化鉀）』溶液，試管內瞬間沉澱出極其鮮豔濃烈的深藍色——「滕氏藍」（Turnbull's blue）沉澱！這鐵證如山地證明：結晶物正是鐵金屬被強酸劇烈腐蝕後生成的硫酸亞鐵（綠礬）！緊接著，調查員採集殘留螺栓金屬進行光譜材質分析：郭富榮在工程標案中宣稱採購的是高抗酸蝕的『SUS 316 鉻鎳鉬不鏽鋼』，然而實測數據顯示，螺栓內部鉻鎳含量嚴重不足，完全是抗酸力極差的劣質『碳素工具鋼鍍鉻仿冒品』！隨後，都會調查員將視線轉向私梟林春生：林春生隨身攜帶的大型帆布背包散發出刺鼻的青磺泉硫磺酸味。搜查其背包，赫然起獲了兩只裝滿地熱谷未稀釋原生高溫青磺泉（實測 pH 1.2）的耐酸保溫瓶，以及一袋剛從北投溪底非法敲鑿、重達五公斤的珍稀國寶級放射性「北投石」原礦！原來林春生為了盜採地熱谷核心湧泉口底下結晶最純的北投石，企圖趁夜翻越護欄，但因護欄鎖死，他竟直接倒出保溫瓶中的沸騰強酸青磺泉反覆澆淋螺栓，劣質鋼材在 pH 1.2 的強酸與 90℃ 高溫催化下短短半小時即被劇烈置換腐蝕穿孔！而承包商郭富榮偷工減料使用假不鏽鋼，則使這起破壞變得更加致命迅速。在化學置換鐵證與起獲的北投石原礦面前，林春生與郭富榮兩人啞口無言，雙雙被警方依破壞公共設施、竊盜國寶礦物及詐欺背信等重罪逮捕收押。",
