    "scienceConcept": "氣體密度比重沈降力學（二氧化硫相對空氣密度約為 2.26 倍）、熱對流流體力學與局部缺氧窒息防護。二氧化硫分子量為 64，遠重於常溫空氣（平均分子量約 29）；在封閉或半封閉無強烈垂直熱對流之密室環境中，冷卻後的二氧化硫氣體會沉降沉積於地面低窪處形成『無形高濃度窒息氣池』，而上方天花板通風口則維持正常空氣流動，形成特殊的空間氣體分層現象。",
    "curriculumMapping": "氣體密度比重沈降力學（二氧化硫相對空氣密度約為 2.26 倍）、熱對流流體力學與局部缺氧窒息防護。二氧化硫分子量為 64，遠重於常溫空氣（平均分子量約 29）；...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：玻璃水杯 1 個、小蘇打粉 1 大匙、白醋半杯、小茶燭 1 顆、打火機。原理：",
    "brief": "陽明山國家公園火山監測站的研究員，昨夜在小油坑舊觀測工作室中，將剛從七星山主峰噴氣孔採集到的極珍貴「深層火山岩漿氣體同位素分析氦氣採樣金屬球」鎖入工作室保險箱中，準備翌日送交中央研究院進行火山爆發預警分析。然而深夜十一點，工作室的安全氣體警報突然大作！當駐警破門而入時，整間工作室瀰漫著濃重的硫磺煙霧，保險箱已被用密碼開啟，採樣金屬球不翼而飛；而工作室的所有對外防爆氣密窗戶全被反鎖，僅有天花板的一具小型抽風扇在轉動，形成一間令人匪夷所思的「毒氣密室」！",
    "storyCause": "陽明山國家公園火山監測站的研究員，昨夜在小油坑舊觀測工作室中，將剛從七星山主峰噴氣孔採集到的極珍貴「深層火山岩漿氣體同位素分析氦氣採樣金屬球」鎖入工作室保險箱中，準備翌日送交中央研究院進行火山爆發預警分析。然而深夜十一點，工作室的安全氣體警報突然大作！當駐警破門而入時，整間工作室瀰漫著濃重的硫磺煙霧，保險箱已被用密碼開啟，採樣金屬球不翼而飛；而工作室的所有對外防爆氣密窗戶全被反鎖，僅有天花板的一具小型抽風扇在轉動，形成一間令人匪夷所思的「毒氣密室」！",
    "storyProcess": "這起詭異的「火山毒氣密室失竊案」引發高度緊張，都會調查員受命迅速展開現場勘查。案發前後在小油坑遊憩區逗留的涉案嫌疑人有三位：專研火山氣體動力學的博士後研究員高啟峰、火山監測站資深儀器校準技師蔡榮德、以及受僱在小油坑停車場值班的夜間保全杜振興。高啟峰稱自己當時在小油坑觀景台架設長焦相機拍夜間熱成像；蔡榮德稱自己在停車場車內小憩；杜振興稱自己在巡視公廁與步道。現場地面沒有任何被鑽孔或強行破壞的痕跡，門鎖為精密電子機械鎖，內側插著鑰匙。最不可思議的是：工作室內部的地面處二氧化硫濃度高達危險的 50 ppm，但站在屋內椅子高度（約 1.2 公尺以上），空氣中的二氧化硫濃度竟然驟降至安全的 2 ppm！",
    "storyClimax": "都會調查員立即運用 108 課綱地球科學與國中理化的『氣體密度比重與流體分層力學』展開破密：調查員指出，二氧化硫（SO₂）的分子量是 64，是常溫空氣（約 29）的 2.2 倍重！嫌犯利用了小油坑外圍引流的冷卻地熱硫磺廢氣，透過工作室牆角一條原本用來排放冷凝水的暗渠管線，將濃重的二氧化硫氣體緩慢灌入工作室。由於二氧化硫極重，注入室內後並不會立刻向上擴散，而是如同水一般緊貼著地板緩緩累積，形成一層厚約 60 公分的『隱形毒氣池』！當值班人員坐在椅子上時渾然不覺，但當其彎腰企圖拾取地面文件時，會瞬間吸入高濃度刺激性氣體引發劇烈劇咳暈眩逃出房間，嫌犯則戴著防毒面具趁亂開箱取寶並在室內完成反鎖！都會調查員進一步勘驗天花板抽風扇，發現通風口邊緣黏著一根極細的金屬牽引細絲，正是用來在室外拉動室內門閂插銷的『反鎖牽引機構』！而在技師蔡榮德的工程工程休旅車後車廂內，搜出了一只工業級高防護全罩式綜合防毒面具，面具濾毒罐吸附的微粒經氣相分析，正是小油坑特有的高純度二氧化硫；更在輪胎備胎凹槽內，搜出了那具被厚鋁箔密封的珍貴火山同位素採樣金屬球！原來蔡榮德收受了外國能源探勘公司重金，企圖盜取台灣首度採集到的深層岩漿同位素數據變賣。在流體分層力學與防毒面具微物鐵證面前，蔡榮德無可遁形，當場低頭伏法。",
