    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "溶液凝固點下降原理（Freezing Point Depression）與鹽冰混合物吸熱冷卻熱力學。純水在 0℃ 結冰，而向冰水混合物中加入食鹽（氯化鈉 NaCl）等溶質時，溶質破壞水分子晶格排列，使其凝固點顯著下降（高濃度鹽水冰點可降至 -21℃），並促使冰塊加速融化大量吸收周圍環境熱量；常溫下未加鹽之普通冰淇淋融化速率恆定，若刻意加入鹽冰保冷劑可大幅延長固化時間偽造不在場證明。",
    "curriculumMapping": "溶液凝固點下降原理（Freezing Point Depression）與鹽冰混合物吸熱冷卻熱力學。純水在 0℃ 結冰，而向冰水混合物中加入食鹽（氯化鈉 NaC...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：夾鏈袋大、小各 1 個、冰塊 2 碗、食鹽半碗、果汁 50ml。原理：",
    "brief": "士林夜市慈諴宮前正舉辦「台北夜市百大名店爭霸賽」。蟬聯兩屆冠軍的老字號手工義式冰淇淋名攤，推出了一座耗時三天雕刻、價值不菲且象徵媽祖慈航的特等黑糖珍奶造型冰雕甜品《慈諴盛宴》。按照競賽規章，冰雕將於晚間八點半由評審團親臨攤位品評。然而八點整，店長驚見原本存放在展示專用高透壓克力保溫箱內的冠軍冰雕，竟然整座離奇融化塌陷成一灘毫無美感的黑糖奶水，形同退賽！而更離奇的是，相隔僅十公尺的隔壁競爭冰品攤，其剛調製完成的同款手工冰淇淋，在室溫 30℃ 的炎夏中竟然足足擺放了一個半小時『絲毫未化』，神乎其技地奪下人氣大獎！",
    "storyCause": "士林夜市慈諴宮前正舉辦「台北夜市百大名店爭霸賽」。蟬聯兩屆冠軍的老字號手工義式冰淇淋名攤，推出了一座耗時三天雕刻、價值不菲且象徵媽祖慈航的特等黑糖珍奶造型冰雕甜品《慈諴盛宴》。按照競賽規章，冰雕將於晚間八點半由評審團親臨攤位品評。然而八點整，店長驚見原本存放在展示專用高透壓克力保溫箱內的冠軍冰雕，竟然整座離奇融化塌陷成一灘毫無美感的黑糖奶水，形同退賽！而更離奇的是，相隔僅十公尺的隔壁競爭冰品攤，其剛調製完成的同款手工冰淇淋，在室溫 30℃ 的炎夏中竟然足足擺放了一個半小時『絲毫未化』，神乎其技地奪下人氣大獎！",
    "storyProcess": "老店主悲憤控訴遭到惡意破壞陷害，都會調查員接獲自治會報案後迅速趕抵現場。現場涉案關係人共有三位：隔壁競爭冰攤的青年攤主宋建明、老店聘僱的兼職送冰員林子豪、以及受僱在夜市負責供水洗滌的清潔阿姨張金枝。老店主指控宋建明故意動手腳破壞冰雕；宋建明反駁稱是老店自己製冷機故障，並自豪宣稱自己的冰淇淋之所以一個半小時不融化是因為掌握了『天然植物膠抗融秘方』；送冰員林子豪則聲稱自己七點半把碎冰送到後就一直在廟口看歌仔戲。都會調查員俯身勘驗老店融化的黑糖冰水，發現壓克力保溫箱底部的溫控壓縮機插頭被暗中拔掉；然而更詭異的是隔壁宋建明攤位展示台上那碗在 30℃ 室溫下堅挺不倒的冰淇淋，碗底散發出一股極微弱的鹹味。",
    "storyClimax": "都會調查員立即運用國小五年級與國中理化的『凝固點下降與鹽冰吸熱原理』揭穿這場鬧劇：調查員取來一支便攜式電子溫度計與一支滴管，首先檢驗老店融化的黑糖水，證實壓縮機斷電導致常溫自然融化；接著，調查員將溫度計探頭直接刺入宋建明那碗『神奇不化』的冰淇淋碗底外層夾壁中——讀數瞬間驟降至驚人的「-14.8℃」！在常溫 30℃ 的夏夜戶外，普通冰品絕不可能低於 0℃！都會調查員當眾將宋建明的冰淇淋大碗翻開，展示其雙層夾心碗底的秘密：碗底夾層內裝滿了細碎的冰塊與大量的粗粒食用海鹽！調查員向眾人解釋：鹽溶解於水需要吸收熱量，且鹽水的凝固點遠低於 0℃，這使得鹽冰混合物的溫度迅速暴降至零下十幾度，形成強效的『化學自冷卻冰夾』，從碗底持續提供超低溫冷源，這才是冰淇淋一個半小時不化的真相！與此同時，調查員在老店保溫箱後方的壓縮機散熱孔處，以顯微鏡檢驗，發現散熱風扇被一把粗鹽粒卡死導致過熱跳電斷路！比對鹽粒規格，正是宋建明進口專用的特級義大利海鹽粗粒。原來宋建明為了贏得爭霸賽，一邊偷偷向老店的散熱孔撒粗鹽蓄意毀壞其保溫機關，一邊用鹽冰雙層碗作弊製造自家冰品抗融假象。在確鑿的凝固點下降物理定律與同批海鹽微物鐵證面前，宋建明無從抵賴，當場被取消參賽資格並依毀損罪由警方帶回偵辦。",
