    "scienceConcept": "光波橫波性質偏振光學原理、布魯斯特角（Brewster's angle）與偏光濾鏡消除反射眩光。自然光經非金屬平滑表面（如玻璃櫥窗或大理石地板）反射時，反射光會產生強烈的局部線性偏振；當反射角等於布魯斯特角（玻璃介質約 56°）時，反射光幾乎 100% 變為水平偏振光；利用偏振方向互相垂直（90° 正交）的偏光濾鏡，可完全阻隔櫥窗強烈的反射虛像光線，從而看透玻璃後方隱藏之光學死角與雷射防盜盲區。",
    "curriculumMapping": "光波橫波性質偏振光學原理、布魯斯特角（Brewster's angle）與偏光濾鏡消除反射眩光。自然光經非金屬平滑表面（如玻璃櫥窗或大理石地板）反射時，反射光會...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：偏光太陽眼鏡 1 副、玻璃反光表面（或陽光下的水盆）。原理：",
    "brief": "週五晚間信義商圈人潮洶湧之際，統一時代百貨二樓國際珠寶旗艦專櫃，正展出一套名為「信義之星」的極罕見克拉級頂級藍寶石項鍊，市價超過千萬元。項鍊展示於專櫃中央由高穿透防彈強化玻璃製成的立體多稜面展示櫃中，四周布設了無形的高精度三維雷射光電防盜幕。然而晚間八點二十分，展櫃防盜系統突然發出極微弱的毫秒級脈衝警訊，值班專櫃店員趕到展台前時，展台中央的「信義之星」項鍊已被調包成一串外觀高度仿真的鍍鉻氧化鋯假項鍊，而玻璃罩未留一絲指紋與撬痕，雷射光網更全程未曾發出常規警報！",
    "storyCause": "週五晚間信義商圈人潮洶湧之際，統一時代百貨二樓國際珠寶旗艦專櫃，正展出一套名為「信義之星」的極罕見克拉級頂級藍寶石項鍊，市價超過千萬元。項鍊展示於專櫃中央由高穿透防彈強化玻璃製成的立體多稜面展示櫃中，四周布設了無形的高精度三維雷射光電防盜幕。然而晚間八點二十分，展櫃防盜系統突然發出極微弱的毫秒級脈衝警訊，值班專櫃店員趕到展台前時，展台中央的「信義之星」項鍊已被調包成一串外觀高度仿真的鍍鉻氧化鋯假項鍊，而玻璃罩未留一絲指紋與撬痕，雷射光網更全程未曾發出常規警報！",
    "storyProcess": "百貨安保長立即封鎖二樓空橋出入口與轉運站地下通道，都會調查員受命迅速展開地毯式搜查。當時在展櫃周邊逗留的嫌疑人有三位：國際知名攝影器材代理商產品總監沈家偉、在專櫃挑選婚戒的外商銀行主管趙振華、以及一名身穿清潔制服推著吸塵推車的兼職清潔員黃文成。沈家偉辯稱自己當時正拿著最新款單眼相機拍攝百貨空中天橋夜景；趙振華聲稱自己正在用手機向未婚妻視訊連線確認戒指款式；黃文成則表示自己剛好在吸地毯上的灰塵。專櫃周圍的八角多稜面防彈玻璃在專櫃高功率聚光燈照射下，產生了極其強烈的眩光與多重反射虛像，普通人的肉眼由外往內看根本是一片刺眼的炫光倒影，完全無法看清展台內部的雷射光路結構。",
    "storyClimax": "都會調查員立即運用 108 課綱高中物理的『光之偏振與布魯斯特角定律』展開破案推導：調查員指出，在展廳高照度聚光燈照射下，防彈玻璃櫥窗的反射光線在入射角約 56 度（布魯斯特角 θB = arctan(n) ≈ arctan(1.5) = 56.3°）時，會轉變為純粹的水平偏振光，形成阻礙視線的強大反射眩光幕；但如果配戴特殊的『垂直軸線性偏光鏡片』，水平偏振的反射眩光會被 100% 徹底過濾吸收，而展櫃內部的雷射立體光束在空氣中微塵散射的光路將變得清晰透明一覽無遺！都會調查員轉向沈家偉的專業單眼相機：在長焦鏡頭前端，安裝了一枚昂貴的德國製『高透超薄多層鍍膜圓形偏光鏡（CPL）』！調查員當場取下偏光鏡，透過鏡片旋轉 90 度對準展櫃——原本眩光刺眼的防彈玻璃瞬間變得完全透明無反光，而展台上方那四道隱形的紅外線雷射光束交會點，在偏光鏡的偏振對比下清晰顯現出一條長度約 15 公分的垂直防護死角！這意味著唯有透過偏光鏡消除眩光的人，才能在三秒鐘之內精確繞過雷射束將自製機械軟夾伸入展台完成調包！都會調查員隨即搜查沈家偉隨身攜帶的重型相機腳架，轉開碳纖維中軸底部的配重掛鉤，赫然在空心金屬管內起獲了被黑色絲絨包裹的真品「信義之星」藍寶石項鍊！在無懈可擊的光學偏振物理定律與腳架藏贓鐵證面前，沈家偉面如死灰，當場被上銬帶回法辦，千萬國寶級珠寶完好歸還專櫃。",
