    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：薄壁高腳玻璃杯 1 個（洗乾淨無油）、半杯清水、乾淨食指。原理：",
    "brief": "新莊國際鼓藝節即將開幕，新莊製鼓工藝館正舉辦「台日名匠鼓藝交流展」。由日本京都百年名剎贈送、象徵台日邦誼的一具極珍貴「大正時期手工雕花薄壁朱砂透光水晶慶典聖杯」，陳列於工藝館二樓中央由三面強化隔音木板環繞的特製展台上。然而下午兩點整，工藝館正門前的一面直徑三公尺特大手工醒獅大堂鼓由學徒試敲演練時，二樓展台突然傳來清脆的爆裂巨響——那只市價逾六十萬元的朱砂水晶聖杯竟然在『完全無人碰觸』的情況下，憑空爆碎成無數細小晶片！",
    "storyCause": "新莊國際鼓藝節即將開幕，新莊製鼓工藝館正舉辦「台日名匠鼓藝交流展」。由日本京都百年名剎贈送、象徵台日邦誼的一具極珍貴「大正時期手工雕花薄壁朱砂透光水晶慶典聖杯」，陳列於工藝館二樓中央由三面強化隔音木板環繞的特製展台上。然而下午兩點整，工藝館正門前的一面直徑三公尺特大手工醒獅大堂鼓由學徒試敲演練時，二樓展台突然傳來清脆的爆裂巨響——那只市價逾六十萬元的朱砂水晶聖杯竟然在『完全無人碰觸』的情況下，憑空爆碎成無數細小晶片！",
    "storyProcess": "這起靈異般的「隔空碎杯懸案」引發館方極大震動，競速調查隨即展開，都會調查員受命在兩小時內查明真相。涉案人員有三位：新莊在地新一代金屬音響工程師蔡志豪、老鼓師的大徒弟兼傳統製鼓師傅陳國棟、以及前來採訪報導鼓藝節的外景收音記者陸偉倫。三人均有不在場陳述：蔡志豪稱自己在門口調校低音音響；陳師傅稱自己在大廳指導學徒繃鼓皮；陸記者稱自己在後院採集廟街傳統環境音。都會調查員進入二樓勘查，發現展台周圍毫無任何機械撞擊刮痕，沒有投擲鋼珠或彈珠的痕跡，唯有水晶杯碎片周圍的水泥牆面上，插著一顆極微小的隱形超高功率定向高音微型喇叭（壓電陶瓷揚聲器）！",
    "storyClimax": "都會調查員立即運用 108 課綱國中理化與生活科技的『聲音的共振與頻率共振破壞原理』展開破案推導：調查員收集水晶杯碎片，以雷射測厚儀測得其壁厚僅 0.8mm，屬於高彈性模數鉛鋇水晶。調查員當場取出一只同批出廠的備用薄壁水晶杯，用濕潤的手指輕輕摩擦杯口使其發出清脆的嗡鳴聲，並以手持音訊頻譜分析儀測量其固有振動頻率——讀數精確為「587.3 Hz」（標準高音 D5 頻率）！都會調查員指出：這絕非意外，而是一起利用『共振原理進行的高科技聲學破壞』！兇手預先在展台死角安裝了以鋰電池驅動的壓電高音喇叭，設定在樓下試敲大鼓的同一瞬間，以 587.3 Hz 的精準正弦波頻率發出高達 110 分貝的定向聚焦超強聲波。聲波使水晶杯產生強烈共振，分子晶格劇烈扭曲在 0.5 秒內超越極限爆碎！都會調查員隨即搜查現場人員的手機與設備：在音響工程師蔡志豪的專業音頻工作站筆電中，查獲了五分鐘前剛被刪除的『ToneGenerator_587Hz_Burst.wav』音訊檔案，且其藍牙發射器後台與展台下的微型喇叭 MAC 位址完全吻合！原來蔡志豪代表的現代音響公司因投標鼓藝節全區音響設備標案敗給工藝館推薦的老牌廠商，心懷嫉恨，企圖利用共振聲波毀壞日本贈送的聖杯，製造老工藝館安保不力、大鼓震動有害文物的醜聞以逼退對手。在無懈可擊的聲波固有共振物理實驗與數位藍牙發射鐵證面前，蔡志豪面紅耳赤，低頭伏法。",
