    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "肉豆蔻天然植物性芳香醚/苯丙烯類（Allylbenzene / Phenylpropene derivative，如肉豆蔻醚 Myristicin 與欖香脂素 Elemicin）過量中樞弱麻醉與抗膽鹼能藥理毒理特性。微量肉豆蔻為南洋料理常用芳香香料；若過量（單次攝入逾 5~10 克）經熱脂肪（如全脂煉乳熱奶茶）萃取後，肉豆蔻醚在人體內代謝為具中樞神經活性的代謝產物，引發嗜睡、瞳孔放大、肢體無力甚至短暫順行性失憶（昏睡數小時）；利用薄層色層層析法（TLC）可迅速分離出肉豆蔻醚特異性色帶（Rf = 0.65）。",
    "curriculumMapping": "肉豆蔻天然植物性芳香醚/苯丙烯類（Allylbenzene / Phenylpropene derivative，如肉豆蔻醚 Myristicin 與欖香脂素 ...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：現磨咖啡粉 1 匙、馬克杯、熱開水。原理：",
    "brief": "午後三點正值華新街茶客聚集之際，南洋名店「仰光香醇奶茶館」二樓靠窗卡座突然傳來悶響：一名專門從事雙北東南亞跨國勞務派遣與金流匯兌的知名僑領何振邦，在喝下半杯特調「南洋熱香料印度拉茶」後，突然眼神呆滯、呼吸微弱，整個人面朝下沉重癱倒在餐桌上陷入深度昏睡！而原本放置於其座位旁內裝有 150 萬元台幣當日外籍移工薪資現金的厚重手提皮包，竟然不翼而飛！",
    "storyCause": "午後三點正值華新街茶客聚集之際，南洋名店「仰光香醇奶茶館」二樓靠窗卡座突然傳來悶響：一名專門從事雙北東南亞跨國勞務派遣與金流匯兌的知名僑領何振邦，在喝下半杯特調「南洋熱香料印度拉茶」後，突然眼神呆滯、呼吸微弱，整個人面朝下沉重癱倒在餐桌上陷入深度昏睡！而原本放置於其座位旁內裝有 150 萬元台幣當日外籍移工薪資現金的厚重手提皮包，竟然不翼而飛！",
    "storyProcess": "茶館店員驚駭報警，都會調查員接報迅速封鎖茶館所有出入口。救護人員初步診斷何振邦生命體徵尚稱穩定但處於重度中樞神經麻醉狀態。現場被列入排查的關係人共有三位：何振邦的私人隨行秘書兼外甥陳偉倫、茶館負責調製奶茶的緬甸籍資深拉茶師傅阿欽（Aung San）、以及坐在隔壁卡座戴著遮陽帽不斷催促結帳的南洋乾貨進口商梁國棟。陳偉倫聲稱自己當時只是去一樓洗手間洗手；阿欽師傅用流利的華語指天發誓店內奶茶香料全為合法食品香料；梁國棟則表示自己只是進來吃一盤緬甸甩餅看報紙。都會調查員採集何振邦喝剩的奶茶杯底殘液，杯底呈現一層極為不尋常的暗褐色微細粉末沉澱，散發出一股極其濃烈刺鼻的辛香甜味。",
    "storyClimax": "都會調查員立即運用 108 課綱自然與生物化學的『植物性芳香醚與香料毒理分析』展開現場勘查：調查員取隨身攜帶的矽膠 TLC 展開板與顯色噴霧，對杯底粉末進行快速色層分析。層析展開結果顯示：樣品呈現極為明顯的『肉豆蔻醚（Myristicin）』單一高純度色斑（Rf 值 0.65），完全排除了安眠藥或農藥等化學毒物！調查員當場指出：普通香料奶茶加入的肉豆蔻粉僅約 0.2 克以增添微香；但在何振邦的奶茶殘渣中，測出的肉豆蔻粉含量竟然高達驚人的 15 克！在全脂煉乳的高油脂熱溶環境下，過量的肉豆蔻醚被完全萃取，其代謝產物會強烈抑制中樞神經，造成飲用者在 15 分鐘內如飲烈酒般肢體癱軟、陷入深度昏睡！能如此精確掌握肉豆蔻熱溶萃取比例與藥效發作時間的人，必定具有高超的調味或藥理知識。都會調查員轉向隨行秘書陳偉倫：陳偉倫手腕的運動智慧手錶表扣縫隙中，檢出了一撮未清洗乾淨的肉豆蔻特有網狀假種皮微粒！更致命的是，調閱茶館一樓後巷 CCTV，陳偉倫聲稱上洗手間的時間，實際上是溜到後巷，將裝有 150 萬元現金的皮包塞進了茶館冷卻水塔後方的備用輪胎鋼圈內！原來陳偉倫在海外賭博欠下高利貸，算準舅舅何振邦有下午必喝特濃熱奶茶的習慣，暗中攜帶研磨超細的肉豆蔻粉投毒，企圖製造舅舅心血管疾病突發的假象趁亂盜走移工薪資。在肉豆蔻醚藥理色層分析與水塔起贓鐵證面前，陳偉倫心理防線潰敗，跪地認罪。",
