    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "摩斯電碼（Morse Code）時間脈衝編碼、電磁繼電器聲學共鳴與音頻頻譜分析法。摩斯密碼由點（Dit，長度為 1 單位時間）與劃（Dah，長度為 3 單位時間）組成；利用微型電磁繼電器或音叉在密閉金屬管路中的敲擊聲，可在長短敲擊間傳遞加密英文字母與數字；在封閉地下甬道中，聲波沿金屬通風管衰減極慢，形成特有的聲音通道導波效應。",
    "curriculumMapping": "摩斯電碼（Morse Code）時間脈衝編碼、電磁繼電器聲學共鳴與音頻頻譜分析法。摩斯密碼由點（Dit，長度為 1 單位時間）與劃（Dah，長度為 3 單位時間...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：3號乾電池 1 顆、小電珠（或小 LED）1 顆、導線 1 截。原理：",
    "brief": "空軍三重一村配合新北眷村文化節，展出一批極珍貴的 1950 年代空軍防砲部隊在台海戰役中使用的「一級機密航行電報手抄本與美製美軍軍用跳頻通信晶片」。然而昨夜文化節彩排結束後，地下甬道鐵門深鎖，今晨解鎖巡檢時，展櫃中的軍用跳頻晶片竟不翼而飛！而在地下甬道金屬通風排氣管道內，定時傳出一陣詭異微弱、極富節奏的「嗒-嗒嗒-嗒」機械金屬敲擊聲，循環往復，令早班巡村人員毛骨悚然！",
    "storyCause": "空軍三重一村配合新北眷村文化節，展出一批極珍貴的 1950 年代空軍防砲部隊在台海戰役中使用的「一級機密航行電報手抄本與美製美軍軍用跳頻通信晶片」。然而昨夜文化節彩排結束後，地下甬道鐵門深鎖，今晨解鎖巡檢時，展櫃中的軍用跳頻晶片竟不翼而飛！而在地下甬道金屬通風排氣管道內，定時傳出一陣詭異微弱、極富節奏的「嗒-嗒嗒-嗒」機械金屬敲擊聲，循環往復，令早班巡村人員毛骨悚然！",
    "storyProcess": "園區管理處緊急通報都會調查員到場勘驗。地下防空甬道深達地下兩公尺，長達近百公尺，宛如地下迷宮。昨晚閉館後曾進入地下甬道的三位嫌疑人為：專研冷戰軍事史的業餘文史收藏家何偉倫、負責園區歷史音效設計的青年音響設計師許志豪、以及在眷村擔任長達十年老義工的退役防砲士官長高正發。三人各有說詞：何偉倫稱自己在眷村將軍樓拍日落；許志豪稱自己在地下甬道錄製空調水滴回音；高士官長則稱自己在地面巡視眷村菜園。都會調查員戴上安全帽深入幽暗潮濕的防空坑道，手持高靈敏度指向性麥克風貼近一處鏽蝕的通風鑄鐵管，清晰收錄到一組規律跳動的金屬敲擊脈衝。",
    "storyClimax": "都會調查員立即運用 108 課綱生活科技中的『摩斯密碼編解碼與聲學頻譜分析』展開破案推導：調查員將錄得的金屬敲擊聲輸入頻譜儀，聲音頻率穩定在 2200Hz。依據摩斯電碼時間標準化規則（短音 Dit = 0.2 秒，長音 Dah = 0.6 秒，字元間隔 = 0.6 秒）：第一組脈衝『• — •』（點-劃-點）對應字母『R』；第二組『— — —』（劃-劃-劃）對應『O』；第三組『— • — •』（劃-點-劃-點）對應『C』；第四組『— • —』（劃-點-劃）對應『K』；第五組『• • • —』（點-點-點-劃）對應數字『4』！整串循環敲擊解密出完整代碼：『R-O-C-K-4』（四號地下砲座基座）！都會調查員循著地下甬道分支路徑疾步來到昔日四號高射砲基座下方，在基座水泥防爆牆的一處通風暗孔深處，赫然搜出了一具正在定時運轉的微型電磁繼電器敲擊蜂鳴器，以及被包裹在絕緣海綿防震袋內的珍貴美軍軍用通信晶片！隨後，都會調查員以紫外螢光燈照射三名嫌疑人雙手：在音響設計師許志豪的左手袖扣與指尖上，檢出與電磁蜂鳴器表面完全相同的微量烙鐵助焊劑松香殘留！搜查其工作筆電，後台赫然存有利用微控制器（Arduino）編程發射該段摩斯密碼以通知同夥前來取貨的程式碼。原來許志豪受私人軍事迷以重金五十萬元委託盜取冷戰晶片，企圖利用摩斯密碼金屬管導波在深夜通知園外同夥定位暗中接應。在無可辯駁的摩斯電碼破譯與微控制器編程鐵證面前，許志豪面色如土，當場坦白認罪。",
