    "scienceConcept": "光波橫波性質與偏光片 90 度正交消光阻光物理原理（Crossed Polarizers Extinction）。現代智慧型手機螢幕（LCD / OLED）出廠時內部均貼有特定角度的線性偏光片以過濾雜光；當觀測者配戴具有垂直偏振方向（互相垂直 90 度）之偏光眼鏡或在鏡頭前旋轉偏光濾鏡時，原本明亮發光的液晶螢幕光線會被 100% 徹底阻斷（透光率近乎 0），呈現彷彿手機『黑屏關機』的視覺錯覺詐術。",
    "curriculumMapping": "光波橫波性質與偏光片 90 度正交消光阻光物理原理（Crossed Polarizers Extinction）。現代智慧型手機螢幕（LCD / OLED）出廠...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：手機（螢幕點亮顯示純白背景）、透明文具膠帶 1 卷、偏光太陽眼鏡 1 副。原理：",
    "brief": "週六下午府中商圈徒步區正舉辦一場知名手機品牌「全城尋寶抽旗艦機」街頭快閃活動。主辦單位在徒步區的一處長椅上放置了一台登入特定虛擬錢包、內有剛抽中的價值十萬元「數位虛擬比特幣兌換碼」的展示展示手機。規則規定：在下午四點整第一個親手觸控解鎖螢幕並讀出螢幕八位數動態動態碼的市民即可全額領取。然而四點整時間一到，站在長椅正前方圍觀的十幾名民眾赫然看見：長椅上的手機螢幕竟然是一片漆黑死寂，眾人皆以為手機沒電關機而轉身離去！唯有一名戴著深色墨鏡的男子迅速伸手點擊螢幕，淡定念出動態碼將十萬元獎金一掃而空！",
    "storyCause": "週六下午府中商圈徒步區正舉辦一場知名手機品牌「全城尋寶抽旗艦機」街頭快閃活動。主辦單位在徒步區的一處長椅上放置了一台登入特定虛擬錢包、內有剛抽中的價值十萬元「數位虛擬比特幣兌換碼」的展示展示手機。規則規定：在下午四點整第一個親手觸控解鎖螢幕並讀出螢幕八位數動態動態碼的市民即可全額領取。然而四點整時間一到，站在長椅正前方圍觀的十幾名民眾赫然看見：長椅上的手機螢幕竟然是一片漆黑死寂，眾人皆以為手機沒電關機而轉身離去！唯有一名戴著深色墨鏡的男子迅速伸手點擊螢幕，淡定念出動態碼將十萬元獎金一掃而空！",
    "storyProcess": "現場落選的民眾憤憤不平，指控主辦單位自導自演詐欺，都會調查員受託當場進行調查。被指控與得獎者串通的涉案人員共有三位：活動現場執行副導陳國祥、迅速領走大獎的墨鏡男子張志遠、以及在旁邊擺攤販售二手手機保護貼的攤商郭建宏。陳國祥堅決否認黑箱作業，稱自己親眼看見手機電量 100%；得獎者張志遠辯稱是自己眼力超群、運氣好；攤商郭建宏則聲稱自己只是在旁邊看熱鬧。然而現場所有錄下過程的圍觀民眾手機錄影均明確顯示：四點整那幾秒鐘，長椅上的手機螢幕在陽光下確實呈現徹徹底底的純黑畫面！",
    "storyClimax": "都會調查員立即運用 108 課綱高中物理的『光之偏振與 90 度正交消光阻光原理』當場戳破這場精密的光學調包詐術：調查員取下得獎者張志遠佩戴的那副看似普通的黑框太陽眼鏡，對準長椅上的展示手機。奇蹟出現了——當眼鏡水平放置時，手機螢幕透過鏡片看去是一片正常的明亮彩色畫面，清晰顯示著八位數動態碼；然而當調查員將眼鏡輕輕旋轉 90 度垂直放置時，鏡片中的手機螢幕瞬間變成了『完全漆黑一片』！調查員當眾揭露：這根本不是普通的遮陽墨鏡，而是一副特製的『高消光比線性偏光眼鏡』！接著調查員以鑷子挑起長椅上展示手機的螢幕表層——手機螢幕外層竟然被人巧妙貼上了一層特定角度（45度偏振軸）的高透光偏光防窺膜！在陽光漫射與周圍大理石地面反射的特定偏振光綜合作用下，普通未佩戴特定偏光鏡的肉眼由特定仰角看去，螢幕出射光被外界強偏振光嚴重干擾壓制形成極暗視覺，讓圍觀民眾誤以為手機黑屏當機；唯有預先戴著相應透光角度偏光鏡的張志遠，能不受干擾看透螢幕讀出密碼！隨後，都會調查員搜查郭建宏的手機貼膜攤位，起獲了被裁切剩下的同批特種偏光膜邊角料，且在執行副導陳國祥的 LINE 記事本中，搜出了兩人密謀『以偏光消光製造黑屏勸退人群、由張志遠現身領獎平分十萬獎金』的完整分贓企劃書！在無可辯駁的偏振光物理定律與數位通訊鐵證面前，三人啞口無言，只得乖乖將獎金退回並依背信詐欺罪移送法辦。",
