    "conclusion": "都會調查員立即運用 108 課綱高中物理的『光之偏振與 90 度正交消光阻光原理』當場戳破這場精密的光學調包詐術：調查員取下得獎者張志遠佩戴的那副看似普通的黑框太陽眼鏡，對準長椅上的展示手機。奇蹟出現了——當眼鏡水平放置時，手機螢幕透過鏡片看去是一片正常的明亮彩色畫面，清晰顯示著八位數動態碼；然而當調查員將眼鏡輕輕旋轉 90 度垂直放置時，鏡片中的手機螢幕瞬間變成了『完全漆黑一片』！調查員當眾揭露：這根本不是普通的遮陽墨鏡，而是一副特製的『高消光比線性偏光眼鏡』！接著調查員以鑷子挑起長椅上展示手機的螢幕表層——手機螢幕外層竟然被人巧妙貼上了一層特定角度（45度偏振軸）的高透光偏光防窺膜！在陽光漫射與周圍大理石地面反射的特定偏振光綜合作用下，普通未佩戴特定偏光鏡的肉眼由特定仰角看去，螢幕出射光被外界強偏振光嚴重干擾壓制形成極暗視覺，讓圍觀民眾誤以為手機黑屏當機；唯有預先戴著相應透光角度偏光鏡的張志遠，能不受干擾看透螢幕讀出密碼！隨後，都會調查員搜查郭建宏的手機貼膜攤位，起獲了被裁切剩下的同批特種偏光膜邊角料，且在執行副導陳國祥的 LINE 記事本中，搜出了兩人密謀『以偏光消光製造黑屏勸退人群、由張志遠現身領獎平分十萬獎金』的完整分贓企劃書！在無可辯駁的偏振光物理定律與數位通訊鐵證面前，三人啞口無言，只得乖乖將獎金退回並依背信詐欺罪移送法辦。"
