    "sectorId": "NTP-03",
    "sectorName": "三重/蘆洲・新北大都會公園辰光橋鴨母港",
    "location": "新北大都會公園辰光橋跨河景觀平台旁水岸濕地與鴨母港溝排洪抽水站水閘口",
