    "difficulty": "★★★☆☆",
    "spookiness": "👻☆☆☆☆ (溫和日常)",
    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "酸鹼指示劑酚酞（Phenolphthalein）遇鹼性變紅化學反應與水體中二氧化碳（CO₂）中和褪色原理。無色酚酞溶液在 pH < 8.2 之酸性或中性環境下呈無色透明；在 pH 8.2 ~ 10.0 之弱鹼至強鹼性溶液（如熟石灰 Ca(OH)₂ 或碳酸鈉溶液）中會瞬間轉變為鮮豔耀眼的紫紅色；當鹼性水體持續接觸空氣中之二氧化碳氣體或被微酸性水稀釋中和時，紫紅色會緩慢褪色重回無色。",
    "curriculumMapping": "酸鹼指示劑酚酞（Phenolphthalein）遇鹼性變紅化學反應與水體中二氧化碳（CO₂）中和褪色原理。無色酚酞溶液在 pH < 8.2 之酸性或中性環境下呈...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：透明水杯 1 個裝水、肥皂屑幾粒、酚酞指示劑 2 滴、飲料吸管 1 支。原理：",
    "brief": "週日午後新北大都會公園正在辰光橋下舉辦「雙北青少年環境科學水質監測錦標賽」。蘆洲區幾所國中參賽隊伍剛從親水人工濕地採集了一批天然清澈樣本，裝在密封玻璃桶中準備進行 pH 值檢測評分。然而就在評審團即將驗收前十分鐘，原本清澈透明的 3 號競賽水樣，在倒入現場提供的化學試劑後，整桶水竟然瞬間爆發出極度刺眼奪目的「深紫紅色」，甚至散發出一股難聞的化學漂白水味！評審團當場判定該組學生採集了嚴重的強鹼污染工業廢水，準備取消其參賽資格並通報環保局！",
    "storyCause": "週日午後新北大都會公園正在辰光橋下舉辦「雙北青少年環境科學水質監測錦標賽」。蘆洲區幾所國中參賽隊伍剛從親水人工濕地採集了一批天然清澈樣本，裝在密封玻璃桶中準備進行 pH 值檢測評分。然而就在評審團即將驗收前十分鐘，原本清澈透明的 3 號競賽水樣，在倒入現場提供的化學試劑後，整桶水竟然瞬間爆發出極度刺眼奪目的「深紫紅色」，甚至散發出一股難聞的化學漂白水味！評審團當場判定該組學生採集了嚴重的強鹼污染工業廢水，準備取消其參賽資格並通報環保局！",
    "storyProcess": "參賽學生委屈痛哭，誓言採水時水質清澈見底、旁邊還有小蝌蚪游泳，絕無可能污染。都會調查員受命進行競速破案。現場涉案關係人共有三位：負責提供競賽公用化學檢驗試劑的化學器材贊助商林志豪、負責抽水站排洪閥門值班的技工彭德全、以及隔壁獲得第一名領先的私立學校指導教練高振剛。林志豪辯稱自己的試劑都是合格出廠產品；彭德全堅稱排洪閘門緊閉未曾排放一滴工業廢水；高教練則稱讚自己的學生採樣嚴謹。都會調查員俯身勘驗那桶深紫紅色的水樣，取 pH 電極筆浸入測量，顯示其 pH 值高達 10.5，確實呈現強鹼性。",
    "storyClimax": "都會調查員立即運用 108 課綱國小自然與國中理化的『酸鹼指示劑酚酞與二氧化碳中和特性』展開科學鑑識：調查員首先檢視林志豪贊助的試劑瓶，瓶標註明為『廣用酸鹼指示劑』，但滴入水中卻只有深紫紅單一顏色，調查員拿出隨身試紙化驗，揭穿那根本不是廣用指示劑，而是高濃度的『酚酞乙醇溶液』！接著，調查員取出一支透明吸管，插入那桶深紫紅色的鹼性水中，深吸一口氣對著吸管持續向水裡吹氣（人體呼出的氣體富含二氧化碳 CO₂）。隨著氣泡不斷翻滾，二氧化碳溶於水生成碳酸（H₂CO₃），持續中和鹼性溶液——短短一分鐘內，原本深紫紅色的水竟然逐漸變淺、最後完全褪色變回無色透明！然而，水質澄清後，水底赫然沉澱出一層白色的微細粉末！都會調查員以刮勺取出粉末檢驗，確認為『碳酸鈣（CaCO₃）』沉澱！這鐵證如山地證明：這桶水原本是弱鹼性含有游離鈣離子的熟石灰水，有人在學生採樣桶蓋內側蓄意塗抹了濃稠的氫氧化鈣（熟石灰）粉末，當水注入晃動時，熟石灰迅速溶解使水質鹼度暴增，一遇酚酞便化為紫紅！都會調查員隨即搜查現場三人的背包與工作推車：在私校教練高振剛的教練帆布包夾層中，起獲了一只沾滿白色熟石灰粉末的膠水刷，其手機通訊軟體查獲其給林志豪轉帳五萬元購買酚酞並要求『搞砸 3 號桶』的通聯記錄！原來高振剛為了保證自己學校隊伍奪冠並獲得海外保送名額，不惜暗中動手腳陷害競爭對手。在二氧化碳中和褪色實驗與碳酸鈣沉澱微物鐵證面前，高振剛與林志豪無從抵賴，當場被取消資格並由警方帶回追究偽造公務競賽之法律責任，學生沉冤得雪。",
