    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：白紙 1 張、棉花棒 1 支、檸檬汁、稀釋小蘇打水、陽光（或紫光燈）。原理：",
    "brief": "台北當代藝術館慶祝建館紀念，在二樓歷史檔案館特展室展出一份被譽為國寶級市政文物的 1921 年日治台北市役所建城原始「全島地籍特許圖藍圖」。然而特展揭幕當天清晨，展館策展員驚恐發現：展示櫃鎖鏈完好，但玻璃櫃內原本深藍底白線的百年經典工程藍圖，竟然通體變成了一張泛黃枯槁、線條完全消失的「空白厚羊皮紙」！若無法在下午市長開幕剪綵前找回或還原這份國寶地籍圖，這場跨越百年的市政歷史大展將宣告全面破產！",
    "storyCause": "台北當代藝術館慶祝建館紀念，在二樓歷史檔案館特展室展出一份被譽為國寶級市政文物的 1921 年日治台北市役所建城原始「全島地籍特許圖藍圖」。然而特展揭幕當天清晨，展館策展員驚恐發現：展示櫃鎖鏈完好，但玻璃櫃內原本深藍底白線的百年經典工程藍圖，竟然通體變成了一張泛黃枯槁、線條完全消失的「空白厚羊皮紙」！若無法在下午市長開幕剪綵前找回或還原這份國寶地籍圖，這場跨越百年的市政歷史大展將宣告全面破產！",
    "storyProcess": "展館隨即啟動最高等級文資緊急調查，都會調查員受命迅速排查昨夜滯留檔案室的三名嫌疑人：負責歷史文獻數位掃描建檔的數位影像專家高偉成、負責二樓古董木窗修繕的資深木雕師傅林阿水、以及一名以研究日治總督府建築著名的日本客座建築史學者藤田浩司。高偉成稱自己昨晚十點把高解析檔案備份到雲端後就離開；林師傅稱自己在走廊刨木料；藤田教授則表示自己在檔案室閱讀昭和年間的建築工務日誌。都會調查員仔細勘查展櫃內那張空白的羊皮紙，發現紙張纖維完整，且表面散發出一股淡淡的特殊還原性弱酸與草酸氣味，桌角遺留著一只被清洗乾淨的微型滴管。",
    "storyClimax": "都會調查員立即運用 108 課綱自然與生活科技中的『氰版藍曬法光化學氧化還原反應』展開破案推導：調查員指出，日治時期的工程藍圖全為『氰版照相法（Cyanotype）』製成，其深藍色發色基團為不溶於水的普魯士藍複合鐵鹽；普魯士藍雖然極耐日光，但遇到草酸或弱鹼性還原劑時，三價鐵會被可逆性還原漂白，導致深藍色完全褪去變成無色透明的亞鐵鹽，製造古圖憑空消失的假象！調查員當機立斷：這張看似空白的羊皮紙正是遭化學漂白的原件！都會調查員取來一盞便攜式高功率 365nm 長波紫外線消毒燈，並以弱酸性過氧化氫微霧均勻噴灑羊皮紙表面進行光催化氧化顯影——奇蹟在大廳眾人眼前震撼重現：只見隨著紫外光強烈激發，原本泛白的紙面上，被氧化的二價鐵瞬間重新結合成無比深邃純淨的「普魯士藍」，一條條精緻繁複的 1921 年台北市役所原始街道、城廓、地下排水系統與防空暗堡線條躍然紙上，百年國寶工程藍圖神乎其技地被完全救活！與此同時，都會調查員以化學試劑檢驗三名嫌疑人的雙手：數位影像專家高偉成的公事包內，起獲了一只裝有草酸還原漂白劑的滴管，且其高階平板電腦中，存有一份昨晚九點私自下載的未加密原始地籍藍圖高解析掃描檔，其通訊軟體查獲其以八十萬元代價答應替海外私人古地圖拍賣行『以化學漂白毀滅公家真品、伺機以高仿複製品調包出境』的犯罪協議！在光化學氧化還原的普魯士藍鐵證面前，高偉成雙膝跪地，坦承全部犯罪事實，百年台北市政歷史藍圖完璧歸趙。",
