    "conclusion": "都會調查員立即運用 108 課綱自然與生活科技中的『氰版藍曬法光化學氧化還原反應』展開破案推導：調查員指出，日治時期的工程藍圖全為『氰版照相法（Cyanotype）』製成，其深藍色發色基團為不溶於水的普魯士藍複合鐵鹽；普魯士藍雖然極耐日光，但遇到草酸或弱鹼性還原劑時，三價鐵會被可逆性還原漂白，導致深藍色完全褪去變成無色透明的亞鐵鹽，製造古圖憑空消失的假象！調查員當機立斷：這張看似空白的羊皮紙正是遭化學漂白的原件！都會調查員取來一盞便攜式高功率 365nm 長波紫外線消毒燈，並以弱酸性過氧化氫微霧均勻噴灑羊皮紙表面進行光催化氧化顯影——奇蹟在大廳眾人眼前震撼重現：只見隨著紫外光強烈激發，原本泛白的紙面上，被氧化的二價鐵瞬間重新結合成無比深邃純淨的「普魯士藍」，一條條精緻繁複的 1921 年台北市役所原始街道、城廓、地下排水系統與防空暗堡線條躍然紙上，百年國寶工程藍圖神乎其技地被完全救活！與此同時，都會調查員以化學試劑檢驗三名嫌疑人的雙手：數位影像專家高偉成的公事包內，起獲了一只裝有草酸還原漂白劑的滴管，且其高階平板電腦中，存有一份昨晚九點私自下載的未加密原始地籍藍圖高解析掃描檔，其通訊軟體查獲其以八十萬元代價答應替海外私人古地圖拍賣行『以化學漂白毀滅公家真品、伺機以高仿複製品調包出境』的犯罪協議！在光化學氧化還原的普魯士藍鐵證面前，高偉成雙膝跪地，坦承全部犯罪事實，百年台北市政歷史藍圖完璧歸趙。"
