    "brief": "松山文創園區原創設計特展VIP閉門展間內，一件以台灣百年肖楠木與金屬結合的限量工藝特獎獎座，在開展前一小時被發現失竊。展間門窗從內部反鎖，宛如一樁不可思議的『密室失竊案』。主辦單位焦急萬分，若無法準時開展，將面臨巨大的商業信譽損害。",
    "storyCause": "松山文創園區原創設計特展VIP閉門展間內，一件以台灣百年肖楠木與金屬結合的限量工藝特獎獎座，在開展前一小時被發現失竊。展間門窗從內部反鎖，宛如一樁不可思議的『密室失竊案』。主辦單位焦急萬分，若無法準時開展，將面臨巨大的商業信譽損害。",
    "storyProcess": "都會調查員與信義分局警員封鎖現場。經勘查，厚重的檜木大門鎖舌完好無撬痕。在場關係人包括：策展總監梁偉峰、燈光展場設計師周敏萱、以及負責夜間清潔的承包商工頭徐德海。周敏萱聲稱展品昨晚由她親自放入展櫃鎖上；梁偉峰堅稱昨夜所有人都在一樓展覽辦公室對合約；徐德海則稱自己整晚都在中庭清掃落葉，根本沒碰過二樓鑰匙。",
    "storyClimax": "面對看似毫無縫隙的密室，都會調查員並未被假象迷惑。調查員關閉展間所有吸頂照明，取出一支高功率綠光雷射指示筆（波長 532nm），平射掃描整個房間的高空區域。奇蹟出現了：在距地面 3.5 公尺高的挑高天花板通風長窗下方，綠光雷射束竟然映照出一條極其濃密、直徑約 30 公分的明亮光斑通道（廷得耳效應光柱）！而房間其他區域空氣澄澈無光。調查員指出：松山菸廠老通風窗八十年來沉積了大量微細煙草纖維膠體，平時靜止無光，唯有在最近三小時內有人強行推開該通風窗，才會揚起這道至今仍在漂浮的廷得耳粉塵光柱！隨後，調查員在中庭通往通風窗的維修鐵梯扶手上，以紫外光驗出了周敏萱所戴防滑手套留下的特殊螢光標記。周敏萱自知無法自圓其說，含淚坦承因不滿策展總監剽竊其設計心血，才趁夜推窗攀爬將獎座藏匿於菸廠老鍋爐房夾層。工藝獎座隨即被安全取回，密室真相大白！",
