    "brief": "華山百年產業記憶展覽現場，一件清代大稻埕外銷歐美之『台灣樟腦局官方認證紅銅拓印版』，在開展倒數三十分鐘被發現失蹤。展台周圍散發出一股刺鼻濃郁的芳香氣味，地上留有幾滴不明無色揮發性液體。工作人員頭暈目眩，無法判定犯案者究竟使用了何種化學手段。",
    "storyCause": "華山百年產業記憶展覽現場，一件清代大稻埕外銷歐美之『台灣樟腦局官方認證紅銅拓印版』，在開展倒數三十分鐘被發現失蹤。展台周圍散發出一股刺鼻濃郁的芳香氣味，地上留有幾滴不明無色揮發性液體。工作人員頭暈目眩，無法判定犯案者究竟使用了何種化學手段。",
    "storyProcess": "都會調查員與忠孝東路派出所員警馳援現場。涉案嫌疑人鎖定三人：展品策劃研究員沈宇凡、園區古董咖啡館老闆高瑞祥、以及前來洽公的日籍文獻代理商佐藤健一。沈宇凡聲稱剛才展台一切正常；高瑞祥表示自己只是路過送咖啡外賣；佐藤健一則聲稱自己在紅磚區拍攝日治老建築窗框。",
    "storyClimax": "面對刺鼻氣味，都會調查員並未退縮。調查員觀察展台下方的中央空調冷氣金屬回風管，發現金屬管壁因低溫（約 16°C）凝結出一層極薄的白色霜狀物質。調查員取出便攜式冰水不鏽鋼杯貼近氣味源頭，短短一分鐘內，空氣中的揮發氣體遇到冰冷杯壁，立刻凝華出細密、優雅的雪白針狀微晶體！都會調查員透過放大鏡指出：這是高純度樟腦蒸氣遇冷凝華的物理現象！嫌犯將松節油與昇華樟腦混合加熱，利用樟腦的強烈氣味掩蓋其塗抹於防盜螺絲上的高腐蝕性強溶劑，在短短五分鐘內卸下了紅銅拓印版。隨後，調查員使用紫外光照向高瑞祥外賣咖啡箱底部：外賣箱保溫層內赫然藏匿著正在揮發樟腦晶體、被毛巾包裹的清代紅銅拓印版！在昇華冷凝物理結晶與現場起獲物證面前，高瑞祥無法狡辯，承認自己因咖啡館虧損，受私藏家委託偷盜拓印版抵債。國寶銅版完好歸還展館！",
