    "curriculumMapping": "釹鐵硼（NdFeB）強磁性物理學、力矩平衡與地磁偏角（Magnetic Declination）。天然樟木神像落鼻結構採清代木工傳統暗榫（Tenon and M...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：強力釹鐵硼小磁鐵 1 塊、鐵質迴紋針 1 個、木質書桌（厚度約 2~3 公分）。原理：",
    "brief": "農曆正月初六清水祖師誕辰大祭前夕，清水巖正殿突然爆發騷動：神龕中的鎮殿祖師木雕神像的鼻子竟當著上百名信眾面前離奇脫落（落鼻），引發全場一片驚恐！與此同時，神像胸前懸掛的清光緒年間御賜『功資拯濟』古金牌竟不翼而飛！信眾紛紛議論是否大難臨頭，現場秩序瀕臨失控。",
    "storyCause": "農曆正月初六清水祖師誕辰大祭前夕，清水巖正殿突然爆發騷動：神龕中的鎮殿祖師木雕神像的鼻子竟當著上百名信眾面前離奇脫落（落鼻），引發全場一片驚恐！與此同時，神像胸前懸掛的清光緒年間御賜『功資拯濟』古金牌竟不翼而飛！信眾紛紛議論是否大難臨頭，現場秩序瀕臨失控。",
    "storyProcess": "都會調查員與萬華分局員警迅速介入維持秩序。神像被供奉於玻璃神龕內，神龕鎖頭無破壞痕跡。排查鎖定案發時站在神龕最近處的三人：佛具金飾修繕匠人陳金塗、廟宇祭典主委林宏達、以及前來採訪民俗節慶的民俗攝影記者黃國峰。陳金塗自稱只是在旁瞻仰神像金身；林宏達聲稱自己正在指揮信眾排隊；黃國峰則表示自己全程都在透過長焦鏡頭拍照。",
    "storyClimax": "面對神蹟降臨與群眾恐慌，都會調查員保持高度理性。調查員取出專業地磁羅盤走向神龕前排查。當走近佛具匠人陳金塗身旁約一公尺時，羅盤指針突然發生劇烈顫抖，磁針偏轉了整整 42 度（地磁偏角異常反轉）！都會調查員果斷指出：神龕周圍並無大型鐵磁結構，如此劇烈的磁場畸變，代表現場存在高達 1.2 特斯拉（Tesla）以上的釹鐵硼超強力稀土磁鐵！調查員要求陳金塗脫下寬大的長袍馬褂：在其特製的右側寬大衣袖內緣，赫然縫製著一枚直徑達五公分的圓形強力強磁環，且從其內衣貼身暗袋中搜出了被磁鐵吸附、用紅布緊緊包裹的清代古金牌！調查員還原真相：陳金塗利用早年替廟宇修繕神像的機會，暗中在祖師鼻榫處植入了一枚微型鐵芯；方才他借由假裝合十參拜，將袖中強磁環貼近神龕玻璃，強大磁吸力瞬間吸脫木榫引發『落鼻神蹟』引起全場尖叫混亂，再趁機以特製細長磁力軟索伸入神龕通風孔竊走金牌！真相大白，信眾恍然大悟，陳金塗被依法移送法辦，古金牌回歸神殿！",
