    "storyClimax": "面對漆黑不見底、散發濃郁發酵氣味的大菁染桶，都會調查員並未盲目撈取十多個大桶。調查員敏銳觀察到其中一個編號『七號』的染桶蓋邊緣被特製的矽膠密封圈緊緊鎖死，且桶蓋中央安裝有一具不顯眼的小型手動加壓充氣閥。都會調查員指出：這是運用國小高年級自然科學中『笛卡爾浮沉子』的機械機關！調查員旋鬆該密封加壓閥釋放桶內氣壓：隨著氣壓驟降，深藏於染液底部、原本因受壓氣體壓縮下沉的一個特製雙層防水透明密封筒，在浮力恢復大於重力的瞬間，咕嘟咕嘟自主上浮至染液表面！打開密封筒，那塊失蹤的清代木刻藍染印花大版赫然完好無損地藏在其中！調查員隨即檢驗三人指紋：加壓閥與密封圈上清晰採集到了二代接班人張家瑋的指紋。原來張家瑋因投資虛擬貨幣欠債，企圖借由魔術般的失蹤手法將古木刻版藏於染桶，待展覽結束後再偷偷撈起轉賣。在浮力機關與科學印證下，張家瑋羞愧低頭認罪，家傳百年文物安然脫險！",
