    "storyCause": "鶯歌國際陶瓷博覽會開幕當天，尖山埔老展館展出號稱自清光緒年間宮廷御窯流傳之『鐵紅釉暗刻蓮花茶盞』，標價高達新台幣兩百萬元。然而在開展兩小時前，一位匿名古物愛好者向主辦單位密報：目前展台上的特獎茶盞已被贗品調換，展出的只是一只粗製濫造的現代熱敏變色假古董！若在博覽會上公開拍賣，鶯歌陶藝界聲譽將毀於一旦！",
    "storyProcess": "都會調查員與鶯歌分駐所警員趕赴現場排查。涉案嫌疑人聚焦三人：展品出借人兼陶藝商人黃榮發、鶯歌資深燒窯技師老郭、以及展館文創禮品部主管許雅婷。黃榮發一口咬定自己的藏品百分之百是清代真品，怒斥調查員無事生非；老郭表示自己昨晚一直在檢修展示射燈；許雅婷則表示自己剛布置好展台宣傳品。",
    "storyClimax": "面對肉眼看似古樸、色澤深沉油亮的茶盞，都會調查員並未動用會破壞陶瓷的酸鹼試劑。調查員運用 108 課綱生活科技中的『熱敏變色物理反應原理』，向展館茶席借來一壺約 55°C 的溫熱水。都會調查員當著所有媒體與評審面前，將溫熱水緩緩淋在茶盞外壁。驚人的物理現象瞬間發生：原本沉穩古樸的深黑褐色『鐵紅釉』，在熱水淋下的三秒鐘內，表層有機塗層瞬間由黑變為完全透明，底層赫然顯現出一行清晰的現代雷射防偽雕刻英文字樣：『Made in 2025 - Modern Ceramic Art Studio』！全場一片譁然！都會調查員冷靜指出：真正的清代高溫鐵紅釉是鐵離子在高溫晶格中的化學發色，永不褪色；而這只贗品使用的是熱敏變色微膠囊噴漆覆蓋現代茶盞。隨後，調查員在黃榮發轎車後車廂的防震密碼箱中，搜出了被絲綢包裹的真正清代古董茶盞。黃榮發自導自演企圖用贗品洗劫高額拍賣金的騙局被當場粉碎！",
