    "scienceConcept": "阿基米德浮力定律（Archimedes' Principle）與材料密度（Density）測定。純金（24K Gold）密度極高，達 19.3 g/cm³；而外觀酷似黃金的黃銅（Cu-Zn 合金，約 8.5 g/cm³）或黃鐵礦（愚人金 FeS2，約 5.0 g/cm³）密度遠低於黃金。利用流體靜力天平（Hydrostatic Balance）分別測量物體在空氣中的真實重力（W1）與浸沒於純水中的視重（W2），根據密度公式 ρ = W₁ / (W₁ − W₂) × 1.0 g/cm³，即使外形尺寸或鍍金完全相同，密度差亦高達兩倍以上，無從隱匿。",
    "curriculumMapping": "阿基米德浮力定律（Archimedes' Principle）與材料密度（Density）測定。純金（24K Gold）密度極高，達 19.3 g/cm³；而外...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：量筒 1 個（或細長有刻度透明奶瓶/量杯）、金屬鑰匙 1 串、清水、電子秤。原理：",
    "brief": "金瓜石黃金博物館特展廳內，一件日治大正時期金瓜石礦業所所長贈予總督府之『本山純金開採紀念懷錶』（外殼為純金打造，具有百年歷史工藝價值），在閉館盤點時被防盜天平感應到微小的重力異常。天平讀數顯示總重均為 250 公克，但博物館安全晶片卻發出警報，懷疑國寶級黃金懷錶已被高手以等重高仿鍍金品調包！",
    "storyCause": "金瓜石黃金博物館特展廳內，一件日治大正時期金瓜石礦業所所長贈予總督府之『本山純金開採紀念懷錶』（外殼為純金打造，具有百年歷史工藝價值），在閉館盤點時被防盜天平感應到微小的重力異常。天平讀數顯示總重均為 250 公克，但博物館安全晶片卻發出警報，懷疑國寶級黃金懷錶已被高手以等重高仿鍍金品調包！",
    "storyProcess": "都會調查員與金瓜石派出所員警第一時間封鎖園區出口。涉案排查人員鎖定三人：特展策展人潘建銘、資深古董鐘錶維修師傅陸志祥、以及金瓜石在地金雕工藝家曾文秀。三人在案發一小時內均曾打開展櫃保養懷錶。陸志祥堅稱自己只是上發條測試擺輪走時；潘建銘表示自己在確認解說牌文案；曾文秀稱自己在臨摹懷錶背面的浮雕花紋。",
    "storyClimax": "面對兩只外觀光澤、花紋、甚至電子天平秤重完全一模一樣（皆為 250.0 公克）的懷錶，一般肉眼完全無法分辨。都會調查員冷靜運用 108 課綱自然科學『阿基米德浮力比重法』建立現場檢測台：調查員取出一台高精度便攜式吊掛天平與裝滿純水的量筒，將受檢懷錶用極細尼龍絲懸吊浸沒於水中。測量結果出爐：受檢懷錶在水中的視重（W2）為 220.6 公克，水中浮力損失（W1 - W2）高達 29.4 公克，對應排水體積為 29.4 cm³！計算其密度為：250.0 / 29.4 = 8.50 g/cm³！都會調查員當場宣告：這絕非純金（密度 19.3 g/cm³，若為純金排水量僅能有 12.95 cm³）！這是一只以黃銅（密度 8.5 g/cm³）精工車削、表面電鍍微米純金的假懷錶！調包鐵證如山。隨後，調查員在鐘錶維修師陸志祥的專業零件工具箱假底層，起獲了沉甸甸的真品純金懷錶（水中排水量實測精準為 13.0 cm³）！在阿基米德浮力定律面前，陸志祥面如死灰，坦承企圖以贗品偷換真金還賭債。金瓜石百年黃金珍寶物歸原主！",
