    "conclusion": "面對兩只外觀光澤、花紋、甚至電子天平秤重完全一模一樣（皆為 250.0 公克）的懷錶，一般肉眼完全無法分辨。都會調查員冷靜運用 108 課綱自然科學『阿基米德浮力比重法』建立現場檢測台：調查員取出一台高精度便攜式吊掛天平與裝滿純水的量筒，將受檢懷錶用極細尼龍絲懸吊浸沒於水中。測量結果出爐：受檢懷錶在水中的視重（W2）為 220.6 公克，水中浮力損失（W1 - W2）高達 29.4 公克，對應排水體積為 29.4 cm³！計算其密度為：250.0 / 29.4 = 8.50 g/cm³！都會調查員當場宣告：這絕非純金（密度 19.3 g/cm³，若為純金排水量僅能有 12.95 cm³）！這是一只以黃銅（密度 8.5 g/cm³）精工車削、表面電鍍微米純金的假懷錶！調包鐵證如山。隨後，調查員在鐘錶維修師陸志祥的專業零件工具箱假底層，起獲了沉甸甸的真品純金懷錶（水中排水量實測精準為 13.0 cm³）！在阿基米德浮力定律面前，陸志祥面如死灰，坦承企圖以贗品偷換真金還賭債。金瓜石百年黃金珍寶物歸原主！"
