    "id": "CASE-50",
    "num": "50",
    "title": "台灣大學醉月湖水波干涉波節回聲聲學案",
    "subtitle": "平靜水面之聲學鏡面反射（Acoustic Specular Reflection）、聲波相位同相...",
    "sectorId": "TPE-04",
    "sectorName": "大安特區・國立台灣大學醉月湖水榭",
    "location": "大安區國立台灣大學公館校區醉月湖畔水榭與湖心八角亭周邊",
    "district": "大安區（台灣大學公館文教區）",
    "lon": 121.5385,
    "lat": 25.0185,
    "difficulty": "★★★☆☆",
    "spookiness": "👻☆☆☆☆ (平和探索)",
    "subject": "國中理化／國小自然（108課綱生活科學）",
    "scienceConcept": "平靜水面之聲學鏡面反射（Acoustic Specular Reflection）、聲波相位同相干涉（In-phase Interference）與空氣聲速計算。在常溫 20°C 空氣中，聲速精確為 v = 331 + 0.6 × 20 = 343 m/s。當聲波在平靜湖面上傳播時，水面如同高聲阻抗界面產生完全反射；湖心亭距離對岸為固定距離，直達聲波與平靜水面反射聲波在岸邊接收點產生規律的波節相長干涉，形成特有的回聲共鳴時間差；若湖面被化學浮油或波浪干擾，反射相干性會被徹底瓦解，由此可由錄音音訊頻譜戳破不在場證明謊言。",
    "curriculumMapping": "平靜水面之聲學鏡面反射（Acoustic Specular Reflection）、聲波相位同相干涉（In-phase Interference）與空氣聲速計算...",
    "safeClassroomKit": "【108課綱 30秒家庭/教室 DIY 微實驗】：。材料：自己的雙手手掌、開闊平靜湖面或大廣場（距離對岸高樓約 100 公尺以上）。原理：",
    "brief": "台大創校百年歷史文獻特展前夕，典藏於台大校史館、由日治台北帝國大學首任總長幣原坦親筆簽署的『台北帝大創校農事與水利規劃全圖總冊』（全台孤本），在運抵醉月湖畔臨時多功能會議中心時失蹤！現場只留下一段嫌犯以擴音器發布的合成干擾音頻錄音，開展在即，校方與文化部無比焦急。",
    "storyCause": "台大創校百年歷史文獻特展前夕，典藏於台大校史館、由日治台北帝國大學首任總長幣原坦親筆簽署的『台北帝大創校農事與水利規劃全圖總冊』（全台孤本），在運抵醉月湖畔臨時多功能會議中心時失蹤！現場只留下一段嫌犯以擴音器發布的合成干擾音頻錄音，開展在即，校方與文化部無比焦急。",
    "storyProcess": "都會調查員與大安分局羅斯福路派出所警員迅速抵達現場封鎖湖畔步道。涉案人員鎖定三人：校史館助理研究員林嘉宏、台大物理系研究生謝廷宇、以及校外骨董二手書店負責人陳百川。陳百川聲稱自己在案發時間（昨晚十點整）一直坐在醉月湖對岸長椅上，並出示了其手機錄下的現場一段『台大傅鐘十點敲鐘湖面清晰回音』錄音作為不在場證明；林嘉宏聲稱自己當時在會議中心整理桌椅；謝廷宇則表示自己在物理館實驗室做光學實驗。",
    "storyClimax": "面對陳百川看似天衣無縫、含有台大傅鐘鐘聲與醉月湖水鳥鳴叫的手機錄音，都會調查員並未被蒙蔽。調查員將陳百川的手機音訊檔案匯入筆電聲學頻譜分析儀中。調查員當場指出：昨晚十點，醉月湖面正處於吹拂四級東北季風的強風擾動狀態，水面波浪起伏高達 15 公分！根據聲學物理原理，崎嶇波浪表面會使反射聲波相位隨機散射，完全無法產生平靜水面的鏡面聲波同相干涉波節；然而陳百川錄音中的傅鐘回聲，竟然展現出只有在『絕對平靜如鏡水面』下才會出現的完美雙峰同相波節共振，甚至測出了室內封閉長廊特有的 0.08 秒早期高頻反射雜音！這證明：這段所謂的現場湖畔錄音，是陳百川預先在室內走廊播放音頻合成偽造的假錄音！不在場證明瞬間瓦解。隨後，調查員在陳百川停放在新生南路地下停車場的休旅車備胎夾層內，搜出了被防水布嚴密包裹的『台北帝大創校水利全圖總冊』！真相大白，陳百川垂頭喪氣承認因書店經營不善，受委託偷盜圖冊轉售。台大百年創校珍貴文獻安然回歸校史館！",
